action-log.css:
/* the card's design switch: Classic, Feed, Phases and Scrubber, with the switch under the log (on designme.dev it is
   the card's footer tabs). Each design sits centred in the room the card keeps for the tallest of them (--dm-dmy, set by the switch) */
.dm.alg-dm{min-height:0;gap:var(--dm-s-5);padding-top:var(--dm-dmy,0px)}
.alg-dm>.dm-main>*{width:100%}
.alg-dm>.dm-main>.alg{min-height:326px}
.stage-in:has(>.alg-dm){align-self:auto;display:block}
/* the three new designs: every kind of step has its icon on a grey tile (the apps their own marks on a white one); lines
   are grey and the steps' marks a mid grey (--dm-alg-x-mark, 3:1 on the surface). Colour is kept for meaning: the accent on
   the step at work and on where the run has got to, green for what passed, red for what failed and for lines out, green
   for lines in */
:is(.alg-lf,.alg-ph,.alg-sc){--dm-alg-x-mark:color-mix(in srgb,var(--dm-muted) 80%,var(--dm-surface))}
:is(.alg-lf,.alg-ph,.alg-sc) code{font-family:var(--dm-mono);font-size:12px;font-weight:500;letter-spacing:-.01em}
/* the detail a step opens to: code, a diff, a command's output, search results, a pull request or a message */
.alg-x-det{display:flex;flex-direction:column;gap:var(--dm-s-2);font-size:12.5px}
.alg-x-dh{display:flex;align-items:center;gap:var(--dm-s-2);min-width:0;color:var(--dm-muted);font-size:12px}
.alg-x-dh .p{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.alg-x-dh .ib{width:24px;height:24px;margin:-4px -4px -4px auto}
.alg-x-pre{margin:0;padding:var(--dm-s-2) 10px;border-radius:calc(10px * var(--dm-rk));background:var(--dm-chip);font-family:var(--dm-mono);font-size:11.5px;line-height:1.7;font-weight:500;white-space:pre-wrap;word-break:break-word;color:var(--dm-fg2)}
.alg-x-pre .a{display:block;margin:0 -10px;padding:0 10px;background:color-mix(in srgb,var(--dm-add) 7%,transparent);color:var(--dm-add)}
.alg-x-pre .x{display:block;margin:0 -10px;padding:0 10px;background:color-mix(in srgb,var(--dm-del) 6%,transparent);color:var(--dm-del)}
.alg-x-pre .ok{color:var(--dm-ok)}.alg-x-pre .bad{color:var(--dm-bad)}.alg-x-pre .dim{color:var(--dm-muted)}
/* a command's output, on a terminal's dark ground in every theme */
.alg-x-pre.term{background:#171717;color:#e6e6e6}
.alg-x-pre.term .ok{color:#6fdca5}.alg-x-pre.term .bad{color:#ffa3a3}.alg-x-pre.term .dim{color:#b8b8b8}
.alg-x-hits{display:flex;flex-wrap:wrap;gap:6px}
.alg-x-hit i{width:14px;height:10px;border-radius:2px;background:var(--dm-chip);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 60%,transparent)}
.alg-x-card{display:flex;align-items:flex-start;gap:10px;padding:10px;border-radius:calc(12px * var(--dm-rk));background:var(--dm-surface);box-shadow:var(--dm-shadow)}
.alg-x-card .brand{width:18px;height:18px;margin-top:1px}
.alg-x-card b{display:block;font-weight:500;font-size:13px}
.alg-x-card span{display:block;color:var(--dm-muted);font-size:12px}
.alg-x-card .tag{display:inline-flex;margin-top:6px}
.alg-x-wait{display:flex;flex-direction:column;gap:8px;padding:10px;border-radius:calc(10px * var(--dm-rk));background:var(--dm-chip)}
.alg-x-wait i{display:block;height:8px;border-radius:4px;background:linear-gradient(90deg,color-mix(in srgb,var(--dm-fg) 8%,transparent) 0 35%,color-mix(in srgb,var(--dm-fg) 16%,transparent) 50%,color-mix(in srgb,var(--dm-fg) 8%,transparent) 65%) 0 0/250% 100%;animation:shim 1.6s linear infinite}
:root:not([data-style="soft"]) .alg-x-wait i:not(:where([data-style="soft"],[data-style="soft"] *)){background:repeating-linear-gradient(90deg,color-mix(in srgb,var(--dm-fg) 14%,transparent) 0 4px,transparent 4px 6px);animation:none}
/* Feed: a live feed that follows new steps, with a filter for each kind that counts its steps, and a pill to jump back down */
.alg-lf{padding:var(--dm-s-2);display:flex;flex-direction:column}
.alg-lf-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3);padding:6px 10px 10px}
.alg-lf-ht{display:flex;flex-direction:column;min-width:0}
.alg-lf-ht b{font-weight:500}
.alg-lf-st{display:flex;align-items:center;gap:7px;font-size:12.5px;color:var(--dm-fg2);white-space:nowrap}
.alg-lf-gl{width:12px;height:12px;display:grid;place-items:center;flex:none;color:var(--dm-ok)}
.alg-lf-gl .dot{color:var(--dm-accent-mark);animation:algblink 1.4s var(--dm-ease-io) infinite}
@keyframes algblink{50%{opacity:.3}}
.alg-lf-tm{font-size:13px;color:var(--dm-fg2)}
/* the filters are the site's small chips: All, then each kind with how many of its steps have landed */
.alg-lf-f{display:flex;gap:2px;padding:0 6px var(--dm-s-2);overflow-x:auto;scrollbar-width:none;margin-bottom:2px}
.alg-lf-f::-webkit-scrollbar{display:none}
.alg-lf-chip{flex:none}
.alg-lf-chip .n{color:var(--dm-muted);font-variant-numeric:tabular-nums;display:inline-block}
.alg-lf-chip .n.bump{animation:algbump .45s var(--dm-ease)}
@keyframes algbump{40%{transform:translateY(-2px) scale(1.18)}}
.alg-lf-chip.on .n{color:var(--dm-fg2)}
.alg-lf-chip:focus-visible{outline-offset:-2px;border-radius:var(--dm-r-pill)}
/* the feed keeps its height: new steps land at the foot and it follows them, unless you have scrolled back to read */
.alg-lf-vw{position:relative}
.alg-lf-vp{height:316px;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:none;outline:0;-webkit-mask-image:linear-gradient(transparent,#000 10px,#000 calc(100% - 14px),transparent);mask-image:linear-gradient(transparent,#000 10px,#000 calc(100% - 14px),transparent)}
.alg-lf-vp::-webkit-scrollbar{display:none}
.alg-lf-list{list-style:none;margin:0;padding:4px 0 12px;display:flex;flex-direction:column}
.alg-lf-w.shut{visibility:hidden}
.alg-lf-it{border-radius:var(--dm-r-in);transition:background .25s}
@media (hover:hover) and (pointer:fine){.alg-lf-it:hover{background:var(--dm-row)}}
.alg-lf-row{display:flex;align-items:center;gap:10px;width:100%;padding:7px 10px;border-radius:var(--dm-r-in);text-align:left;position:relative}
.alg-lf-row:focus-visible{outline-offset:-2px;border-radius:var(--dm-r-in)}
.alg-lf-ic{position:relative;width:28px;height:28px;border-radius:var(--dm-r-sm);display:grid;place-items:center;flex:none;background:var(--dm-chip);color:var(--dm-fg2);transition:background .3s}
.alg-lf-ic .brand{width:15px;height:15px}
.alg-lf-it[data-k="app"] .alg-lf-ic{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent);color:var(--dm-fg)}
/* on a grey row a step's grey tile turns white */
@media (hover:hover) and (pointer:fine){.alg-lf-it:hover .alg-lf-ic{background:var(--dm-surface)}}
.alg-lf-tx{flex:1;min-width:0;display:flex;flex-direction:column;font-size:13px}
.alg-lf-tx .t{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.alg-lf-tx .d{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.alg-lf-tx .d .a{color:var(--dm-add)}.alg-lf-tx .d .x{color:var(--dm-del)}
.alg-lf-r{display:flex;align-items:center;gap:var(--dm-s-2);flex:none;font-size:12px;color:var(--dm-muted)}
.alg-lf-r .g{width:14px;height:14px;display:grid;place-items:center}
.alg-lf-r .g .spin{width:11px;height:11px;color:var(--dm-accent-mark)}
.alg-lf-r .ok{color:var(--dm-ok)}.alg-lf-r .bad{color:var(--dm-bad)}
.alg-lf-r .g svg{animation:algpop .4s var(--dm-ease)}
@keyframes algpop{from{transform:scale(.3);opacity:0}60%{transform:scale(1.2)}}
/* the step at work: its tile breathes and a grey light runs under it */
.alg-lf-it.run .alg-lf-ic{animation:algbreathe 1.6s var(--dm-ease-io) infinite}
@keyframes algbreathe{50%{opacity:.55}}
.alg-lf-run{display:none;position:absolute;left:48px;right:10px;bottom:2px;height:2px;border-radius:1px;overflow:hidden;pointer-events:none}
.alg-lf-it.run .alg-lf-run{display:block}
.alg-lf-run i{position:absolute;top:0;bottom:0;left:0;width:40%;background:linear-gradient(90deg,transparent,var(--dm-faint),transparent);opacity:.7;transform:translateX(-100%);animation:algrun 1.3s linear infinite}
@keyframes algrun{to{transform:translateX(250%)}}
/* a failed step is red, and nothing on its row is grey */
.alg-lf-it.fail{background:var(--dm-bad-bg)}
.alg-lf-it.fail .alg-lf-tx .d{color:var(--dm-bad)}
.alg-lf-it.fail .alg-lf-r{color:var(--dm-fg)}
.alg-lf-it.fail .alg-lf-ic{background:var(--dm-surface)}
.alg-lf-det{padding:0 10px 10px 48px}
/* the pill that brings you back to the newest steps */
.alg-lf-new{position:absolute;left:50%;bottom:10px;z-index:2;display:inline-flex;align-items:center;gap:6px;height:28px;padding:0 12px 0 10px;border-radius:var(--dm-r-pill);background:var(--dm-raised);color:var(--dm-fg);font-size:12.5px;box-shadow:var(--dm-shadow-pop);transform:translateX(-50%);animation:algup .4s var(--dm-ease)}
.alg-lf-new[hidden]{display:none}
@media (hover:hover) and (pointer:fine){.alg-lf-new:hover{background:var(--dm-row)}}
.alg-lf-new .i{width:12px;height:12px;color:var(--dm-accent-fg,var(--dm-fg))}
@keyframes algup{from{opacity:0;transform:translate(-50%,8px)}}
:root:not([data-style="soft"]) .alg-lf-it.run .alg-lf-ic:not(:where([data-style="soft"],[data-style="soft"] *)){animation:bpblink 1.1s steps(1,end) infinite}
:root:not([data-style="soft"]) .alg-lf-ic:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
:root:not([data-style="soft"]) .alg-lf-run:not(:where([data-style="soft"],[data-style="soft"] *)){height:1px}
:root:not([data-style="soft"]) .alg-lf-run i:not(:where([data-style="soft"],[data-style="soft"] *)){width:100%;background:repeating-linear-gradient(90deg,var(--dm-faint) 0 4px,transparent 4px 7px);opacity:1;transform:none;animation:algmarch .5s steps(3) infinite}
@keyframes algmarch{to{transform:translateX(7px)}}
:root:not([data-style="soft"]) .alg-lf-it.fail:not(:where([data-style="soft"],[data-style="soft"] *)){background:repeating-linear-gradient(135deg,transparent 0 5px,color-mix(in srgb,var(--dm-bad) 10%,transparent) 5px 6px),var(--dm-bad-bg)}
:root:not([data-style="soft"]) :is(.alg-lf-r .g svg,.alg-lf-chip .n.bump):not(:where([data-style="soft"],[data-style="soft"] *)){animation:none}
:root:not([data-style="soft"]) .alg-lf-new:not(:where([data-style="soft"],[data-style="soft"] *)){animation:bpin .3s var(--dm-ease)}
/* Phases: denser, the steps grouped into explore, change, verify and ship, each folding when done, with a minimap on the
   right in the accent: its track a tint of it, a tick for every step (red if it failed) and a line where the run is now */
/* it keeps the room it needs with the last phase open and another opened from the minimap, so it never grows as it plays */
.alg-ph{padding:var(--dm-s-3) var(--dm-s-3) var(--dm-s-2);display:flex;flex-direction:column;gap:var(--dm-s-2);min-height:384px}
.alg-ph-h{display:flex;align-items:center;gap:10px;padding:2px 2px 6px}
.alg-ph-hi{width:32px;height:32px;border-radius:calc(10px * var(--dm-rk));display:grid;place-items:center;flex:none;background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent));transition:background .3s,color .3s}
.alg-ph.fin .alg-ph-hi{background:var(--dm-ok-bg);color:var(--dm-ok)}
.alg-ph-ht{flex:1;min-width:0;display:flex;flex-direction:column}
.alg-ph-ht b{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.alg-ph-st{font-size:12.5px;color:var(--dm-muted);white-space:nowrap}
.alg-ph-sm{color:var(--dm-fg2)}
.alg-ph-ring{position:relative;width:34px;height:34px;flex:none;display:grid;place-items:center;font-size:11.5px;font-weight:500}
.alg-ph-ring svg{position:absolute;inset:0;width:34px;height:34px;transform:rotate(-90deg)}
.alg-ph-ring circle{fill:none;stroke:color-mix(in srgb,var(--dm-line) 70%,transparent);stroke-width:3}
.alg-ph-ring circle.v{stroke:var(--dm-accent-mark,var(--dm-accent));stroke-linecap:round;stroke-dasharray:69.12;stroke-dashoffset:69.12;transition:stroke-dashoffset .6s var(--dm-ease),stroke .4s}
.alg-ph.fin .alg-ph-ring circle.v{stroke:var(--dm-ok)}
.alg-ph-body{display:grid;grid-template-columns:minmax(0,1fr) 10px;gap:var(--dm-s-2);flex:1}
.alg-ph-phs{position:relative;display:flex;flex-direction:column;align-self:start}
/* the phases hang off one grey rail: each joins the next, and its stretch turns a step darker once it is done */
.alg-ph-p{position:relative}
.alg-ph-rl{position:absolute;left:19px;top:34px;bottom:-6px;width:2px;border-radius:1px;background:color-mix(in srgb,var(--dm-line) 80%,transparent);pointer-events:none}
.alg-ph-rl i{position:absolute;inset:0;border-radius:inherit;background:var(--dm-faint);transform-origin:top;transform:scaleY(0);transition:transform .7s var(--dm-ease)}
.alg-ph-p[data-s="done"] .alg-ph-rl i{transform:none}
.alg-ph-phh{display:flex;align-items:center;gap:10px;width:100%;min-height:40px;padding:6px 8px;border-radius:calc(10px * var(--dm-rk));text-align:left;font-size:13px;transition:background .2s}
@media (hover:hover) and (pointer:fine){.alg-ph-phh:hover{background:var(--dm-row)}}
.alg-ph-phh:focus-visible{outline-offset:-2px;border-radius:calc(10px * var(--dm-rk))}
.alg-ph-pg{position:relative;z-index:1;width:24px;height:24px;border-radius:50%;display:grid;place-items:center;flex:none;background:var(--dm-surface);box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--dm-rail) 80%,transparent);font-size:11.5px;font-weight:500;color:var(--dm-muted);transition:background .3s,color .3s,box-shadow .3s}
.alg-ph-pg .radar{width:12px;height:12px}
.alg-ph-p[data-s="run"] .alg-ph-pg{background:var(--dm-accent-bg);box-shadow:none;color:var(--dm-accent-fg,var(--dm-fg))}
.alg-ph-p[data-s="done"] .alg-ph-pg{background:var(--dm-ok-bg);box-shadow:none;color:var(--dm-ok)}
.alg-ph-pn{font-weight:500}
.alg-ph-p[data-s="next"] .alg-ph-pn{color:var(--dm-fg2)}
.alg-ph-pm{flex:1;min-width:0;font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
/* a phase folded to one line still shows what it did, as a bar of its steps in the accent, each as long as it took */
.alg-ph-mix{display:flex;gap:2px;width:44px;height:5px;flex:none;opacity:0;transition:opacity .3s}
.alg-ph-mix i{height:100%;border-radius:2px;background:var(--dm-accent-mark,var(--dm-accent))}
.alg-ph-p[data-s="done"] .alg-ph-phh[aria-expanded="false"] .alg-ph-mix{opacity:1}
.alg-ph-cv{color:var(--dm-muted);display:grid;transition:transform .35s var(--dm-ease)}
.alg-ph-phh[aria-expanded="false"] .alg-ph-cv{transform:rotate(-90deg)}
.alg-ph-acts{list-style:none;margin:0;padding:0 0 4px 34px;display:flex;flex-direction:column}
.alg-ph-a{display:flex;align-items:center;gap:var(--dm-s-2);min-height:28px;padding:3px 8px;border-radius:calc(8px * var(--dm-rk));font-size:12.5px;color:var(--dm-fg2);transition:background .3s}
.alg-ph-a .k{width:18px;height:18px;display:grid;place-items:center;flex:none;border-radius:5px;background:var(--dm-chip);color:var(--dm-fg2);transition:background .3s}
.alg-ph-a .k .brand{width:12px;height:12px}
.alg-ph-a[data-k="app"] .k{background:var(--dm-surface);color:var(--dm-fg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent)}
.alg-ph-a .t{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.alg-ph-a .t b{font-weight:500;color:var(--dm-fg)}
.alg-ph-a .w{font-size:11.5px;color:var(--dm-muted);font-variant-numeric:tabular-nums}
.alg-ph-a.run .t{color:var(--dm-fg)}
.alg-ph-a.fail .t,.alg-ph-a.fail .w{color:var(--dm-bad)}
/* a step the minimap points to flashes grey, and its tile turns white while it does */
.alg-ph-a.flash{animation:algflash 1.2s var(--dm-ease)}
.alg-ph-a.flash .k{background:var(--dm-surface)}
@keyframes algflash{0%,30%{background:var(--dm-hover)}100%{background:transparent}}
.alg-ph-map{position:relative;border-radius:5px;background:var(--dm-accent-bg);margin:6px 0}
.alg-ph-tk{position:absolute;left:1px;right:1px;height:4px;margin-top:-2px;border-radius:2px;background:var(--dm-accent-mark,var(--dm-accent));cursor:pointer;animation:algtk .4s var(--dm-ease) backwards}
.alg-ph-tk.fail{background:var(--dm-bad)}
@keyframes algtk{from{transform:scaleX(0)}}
.alg-ph-now{position:absolute;left:-3px;right:-3px;top:0;height:2px;border-radius:1px;background:var(--dm-accent-mark,var(--dm-accent));transform:translateY(calc(var(--dm-now,0) * var(--dm-mh,300px)))}
.alg-ph.fin .alg-ph-now{opacity:0;transition:opacity .4s}
:root:not([data-style="soft"]) .alg-ph-rl:not(:where([data-style="soft"],[data-style="soft"] *)){width:1px;left:19.5px;background:repeating-linear-gradient(var(--dm-rail) 0 3px,transparent 3px 6px)}
:root:not([data-style="soft"]) .alg-ph-rl i:not(:where([data-style="soft"],[data-style="soft"] *)){transition:transform .4s steps(4,end)}
:root:not([data-style="soft"]) .alg-ph-pg:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 80%,transparent)}
:root:not([data-style="soft"]) .alg-ph-p[data-s="run"] .alg-ph-pg:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:none;background:var(--dm-accent);color:var(--dm-on-accent)}
:root:not([data-style="soft"]) .alg-ph-p[data-s="done"] .alg-ph-pg:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:none}
:root:not([data-style="soft"]) .alg-ph-map:not(:where([data-style="soft"],[data-style="soft"] *)){background:repeating-linear-gradient(0deg,transparent 0 5px,var(--dm-grid) 5px 6px),var(--dm-accent-bg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-accent-mark) 40%,transparent)}
:root:not([data-style="soft"]) .alg-ph-tk:not(:where([data-style="soft"],[data-style="soft"] *)){animation:none;height:3px}
:root:not([data-style="soft"]) .alg-ph-a.flash:not(:where([data-style="soft"],[data-style="soft"] *)){animation:algflashbp .9s steps(3,end)}
@keyframes algflashbp{0%{background:var(--dm-hover)}100%{background:transparent}}
:root:not([data-style="soft"]) .alg-ph-ring circle.v:not(:where([data-style="soft"],[data-style="soft"] *)){stroke-linecap:butt;transition:stroke-dashoffset .4s steps(5,end)}
:root:not([data-style="soft"]) .alg-ph-a .k:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
/* Scrubber: a replay, every step a stop on one track; drag, step or use the arrows, and Live jumps back. The track's
   progress and the knob are the accent, and Live is a chip in the accent's tint */
.alg-sc{padding:var(--dm-s-3);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.alg-sc-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3);padding:2px 2px 0}
.alg-sc-ht{display:flex;flex-direction:column;min-width:0}
.alg-sc-ht b{font-weight:500}
.alg-sc-st{font-size:12.5px;color:var(--dm-muted);white-space:nowrap}
.alg-sc-live{gap:7px;padding:0 11px 0 10px}
.alg-sc-ld{width:7px;height:7px;border-radius:50%;background:var(--dm-muted);flex:none}
/* live: the chip takes the accent's tint and its dot blinks; once the run is done it is green and still */
.alg-sc-live[aria-pressed="true"]{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-fg))}
@media (hover:hover) and (pointer:fine){.alg-sc-live[aria-pressed="true"]:hover{background:color-mix(in srgb,var(--dm-accent) 16%,transparent);color:var(--dm-accent-fg,var(--dm-fg))}}
.alg-sc-live[aria-pressed="true"] .alg-sc-ld{background:var(--dm-accent-mark,var(--dm-accent));animation:algblink 1.4s var(--dm-ease-io) infinite}
.alg-sc.fin .alg-sc-live[aria-pressed="true"]{background:var(--dm-ok-bg);color:var(--dm-ok)}
.alg-sc.fin .alg-sc-live[aria-pressed="true"] .alg-sc-ld{background:var(--dm-ok);animation:none}
/* the track: a stop for every step at the moment it started, a line the accent fills as the run goes, and a knob on the
   step on show */
.alg-sc-tr{position:relative;height:38px;margin:0 10px;cursor:pointer;touch-action:none;outline:0;border-radius:calc(8px * var(--dm-rk))}
.alg-sc-tr:focus-visible{box-shadow:0 0 0 2px var(--dm-focus)}
.alg-sc-ln{position:absolute;left:0;right:0;top:18px;height:3px;border-radius:2px;background:color-mix(in srgb,var(--dm-line) 85%,transparent);overflow:hidden}
