.alg-sc-n{position:absolute;top:19.5px;left:var(--dm-x);width:13px;height:13px;margin:-6.5px 0 0 -6.5px;border-radius:50%;background:var(--dm-surface);box-shadow:inset 0 0 0 2px var(--dm-accent-mark,var(--dm-accent));animation:algn .45s var(--dm-ease) backwards;pointer-events:none;transition:transform .25s var(--dm-ease)}
