.alg-sc-n.on{transform:scale(1.25)}
@keyframes algn{from{transform:scale(0)}60%{transform:scale(1.3)}}
.alg-sc-knob{position:absolute;left:0;top:19.5px;width:25px;height:25px;margin:-12.5px 0 0 -12.5px;border-radius:50%;box-shadow:0 0 0 2px var(--dm-accent-mark,var(--dm-accent));transform:translateX(var(--dm-kx,0px));transition:transform .45s var(--dm-ease),opacity .3s;pointer-events:none;opacity:0}
.alg-sc.has .alg-sc-knob{opacity:1}
.alg-sc-tr.drag .alg-sc-knob{transition:transform .12s linear}
.alg-sc-ax{display:flex;justify-content:space-between;margin:-8px 10px 0;font-size:11.5px;color:var(--dm-muted)}
/* the step on show: what it was and what it did, sliding in from the side it came from */
.alg-sc-view{position:relative;height:214px;overflow:hidden;border-radius:calc(14px * var(--dm-rk));background:var(--dm-wash);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
.alg-sc-card{position:absolute;inset:0;padding:var(--dm-s-3);display:flex;flex-direction:column;gap:10px}
.alg-sc-card.in-r{animation:algcinr .45s var(--dm-ease)}
.alg-sc-card.in-l{animation:algcinl .45s var(--dm-ease)}
.alg-sc-card.out-r{animation:algcoutr .35s var(--dm-ease) forwards}
.alg-sc-card.out-l{animation:algcoutl .35s var(--dm-ease) forwards}
@keyframes algcinr{from{opacity:0;transform:translateX(28px);filter:blur(4px)}}
