@keyframes algcoutl{to{opacity:0;transform:translateX(28px);filter:blur(4px)}}
.alg-sc-ch{display:flex;align-items:center;gap:10px;min-width:0}
.alg-sc-ic{width:32px;height:32px;border-radius:calc(10px * var(--dm-rk));display:grid;place-items:center;flex:none;background:var(--dm-surface);color:var(--dm-fg2);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent)}
.alg-sc-ic .brand{width:17px;height:17px}
.alg-sc-cx{flex:1;min-width:0;display:flex;flex-direction:column;font-size:13px}
