.alg-sc-cm .ok{color:var(--dm-ok)}.alg-sc-cm .bad{color:var(--dm-bad)}
.alg-sc-cm .spin{width:11px;height:11px;color:var(--dm-accent-mark)}
/* in the grey view, the detail's grey blocks turn white */
.alg-sc-view :is(.alg-x-pre:not(.term),.alg-x-wait){background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent)}
