agent-tree.css:
/* the card's design switch: Classic, Cost tree and Cost map, with the switch under the tree (on designme.dev it is the
   card's footer tabs). Each design sits centred in the room the card keeps for the tallest of them (--dm-dmy, set by the switch) */
.dm.atr-dm{min-height:0;gap:var(--dm-s-5);padding-top:var(--dm-dmy,0px)}
.atr-dm>.dm-main>*{width:100%}
.stage-in:has(>.atr-dm){align-self:auto;display:block}
/* the two new designs: each agent has its avatar in the avatar colours (--dm-a, its ink --dm-ai), the orchestrator's is ink.
   Green is done, red needs a fix, and the accent marks what is running */
.atr-x-av{position:relative;width:24px;height:24px;border-radius:var(--dm-r-sm);display:grid;place-items:center;flex:none;background:var(--dm-a);color:var(--dm-ai)}
.atr-x-av .i{width:12px;height:12px;stroke-width:1.9}
.atr-x-g{width:16px;height:16px;display:grid;place-items:center;flex:none;color:var(--dm-faint)}
.atr-x-g .spin{width:11px;height:11px;color:var(--dm-accent-mark)}
[data-s="done"]>.atr-x-g{color:var(--dm-ok)}
[data-s="fail"]>.atr-x-g{color:var(--dm-bad)}
.atr-x-fix{flex:none;background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-shadow)}
@media (hover:hover) and (pointer:fine){.atr-x-fix:hover{background:var(--dm-surface);box-shadow:var(--dm-shadow-pop)}}
/* Cost tree: the tree, with each branch's share of the whole run as a bar. Cost is the accent: each agent takes a step of
   it (--dm-k1 to --dm-k3, each 3:1 or more on the surface), in the bar of the whole run and in its rows, so a row's bar and its
   part of the run match. Lighter steps would drop under 3:1, so the steps run from the accent towards the text colour, and
   in Blueprint's dark theme, where the lime is already light, towards the surface */
