:root:not([data-style="soft"]) .rsu-rc-cut:not(:where([data-style="soft"],[data-style="soft"] *)){background:repeating-linear-gradient(90deg,var(--dm-rail) 0 3px,transparent 3px 6px)}
:root:not([data-style="soft"]) .rsu-rc-ds i:not(:where([data-style="soft"],[data-style="soft"] *)){animation:rsuds .2s steps(2,end) forwards}
:root:not([data-style="soft"]) .rsu-rc-hf:not(:where([data-style="soft"],[data-style="soft"] *)){background:repeating-linear-gradient(135deg,transparent 0 4px,color-mix(in srgb,var(--dm-bad) 30%,transparent) 4px 5px)}
:root:not([data-style="soft"]) .rsu-rc-undo.hold .rsu-rc-hf:not(:where([data-style="soft"],[data-style="soft"] *)){transition:transform 1s steps(10,end)}
/* Recap: the run told back as a timeline of the moments that mattered; hover one and the files it touched light up */
.rsu-rp{display:flex;flex-direction:column;gap:12px}
.rsu-rp-h{display:flex;align-items:center;gap:var(--dm-s-3)}
.rsu-rp-ok{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;flex:none;background:var(--dm-ok-bg);color:var(--dm-ok);animation:rsupop .6s var(--dm-ease) .1s backwards}
@keyframes rsupop{from{transform:scale(.4);opacity:0}60%{transform:scale(1.1)}}
.rsu-rp-ht{display:flex;flex-direction:column;min-width:0}
