.rsu-rp-ht span{font-size:12.5px;color:var(--dm-muted)}
.rsu-rp-files{display:flex;flex-wrap:wrap;gap:6px}
/* the files are the site's file chips; the ones a moment touched take the site's highlight, the accent's tint */
.rsu-rp-fc{transition:background .25s,color .25s,transform .25s var(--dm-ease)}
.rsu-rp-fc code{font-size:11.5px}
.rsu-rp-fc .n{font-size:11.5px;color:var(--dm-muted);font-variant-numeric:tabular-nums}
.rsu-rp-fc.lit{background:var(--dm-sel);color:var(--dm-accent-fg,var(--dm-fg));transform:translateY(-2px)}
.rsu-rp-tw{position:relative;margin:0 -6px}
.rsu-rp-tl{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}
/* the grey line down the timeline draws itself as the moments arrive */
.rsu-rp-rail{position:absolute;left:19px;top:16px;bottom:16px;width:2px;border-radius:1px;background:var(--dm-rail);transform-origin:top;transform:scaleY(var(--dm-p,0));transition:transform .5s var(--dm-ease);pointer-events:none}
.rsu-rp-m{position:relative;display:flex;align-items:center;gap:10px;min-height:38px;padding:4px 6px;border-radius:calc(10px * var(--dm-rk));font-size:13px;opacity:0;transform:translateY(6px);transition:opacity .4s,transform .45s var(--dm-ease),background .2s}
.rsu-rp-m.in{opacity:1;transform:none}
/* the recap sits on the page, not on a panel, so a moment's highlight is a light step of the text colour over whatever is
   behind it, and every tile is white with a dimmed edge, so nothing grey sits on grey */
.rsu-rp-m.on{background:color-mix(in srgb,var(--dm-fg) 4%,transparent)}
