.rsu-rp-mw{font-size:11.5px;color:var(--dm-muted);font-variant-numeric:tabular-nums}
.rsu-rp-end{display:flex;flex-direction:column;gap:8px;opacity:0;transform:translateY(8px);transition:opacity .5s,transform .5s var(--dm-ease)}
.rsu-rp-end.in{opacity:1;transform:none}
.rsu-rp-pr{display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:var(--dm-r-in);background:var(--dm-surface);box-shadow:var(--dm-shadow)}
