/* ---------- Run summary designs ---------- */
{
  const classic = DM.defs['run-summary'];
  // the card has three designs, picked with the switch under the summary (on designme.dev, the card's footer tabs): Classic,
  // the summary as it has always been; Receipt, a receipt of the run with time by phase and a hold to undo; Recap, the run
  // told back as a timeline. The two new ones sum up the same run
  const RSU_FILES = [['PricingCard.tsx', 24, 18], ['tokens.css', 9, 2], ['Pricing.test.tsx', 31, 0]];
  const RSU_PH = [['Explore', 2.3, 'e'], ['Change', 5.6, 'c'], ['Verify', 3.4, 'v'], ['Ship', 1.4, 's']];
  const RSU_TEXT = 'Pricing cards now use spacing tokens\nDone in 12m 40s: 6 files, 14 steps, 182k tokens, $0.84\nPricingCard.tsx +24 −18, tokens.css +9 −2, Pricing.test.tsx +31\nPR #412 is open. Needs you: the yearly badge overlaps the price on a phone';
  // a file's change as five blocks, in proportion to lines in and out
  const rsuBlocks = (a, x) => { const t = a + x, n = Math.min(5, Math.max(1, Math.round(t / 8))), ga = t ? Math.round(a / t * n) : 0; return Array.from({ length:5 }, (_, i) => i < ga ? 'a' : i < n ? 'x' : ''); };
  // a number counting up to its value, a little after it appears: its text changes ten times a second, and lands on the value
  const rsuCount = (c, el, to, fmt, delay) => c.later(delay, () => { let at = -1e9; tween(0, to, REDUCE ? 1 : 1100, (v, p) => { const now = performance.now(); if (p < 1 && now - at < 100) return; at = now; el.textContent = fmt(v); }); });

  // Receipt: a check that draws itself, time by phase, a row of blocks for each changed file, and Undo all, pressed and held
  const RSU_RECEIPT = `<div class="rsu-rc panel keep">
    <div class="rsu-rc-h">
      <span class="rsu-rc-ok" aria-hidden="true"><svg viewBox="0 0 40 40"><circle class="rg" cx="20" cy="20" r="17"/><path class="ck" d="m13 20.5 4.6 4.6L27.5 15"/></svg><i></i><i></i><i></i><i></i><i></i><i></i></span>
      <div class="rsu-rc-ht"><b class="rsu-rc-t">Run complete</b><span class="rsu-rc-s">Finished in 12m 40s</span></div>
      <button class="ib rsu-rc-cp" type="button" aria-label="Copy the summary" data-tip="Copy summary">${I('copy')}</button>
    </div>
    <p class="rsu-rc-title">Pricing cards now use spacing tokens</p>
    <div class="rsu-rc-stats"></div>
    <div class="rsu-rc-phase"><div class="rsu-rc-pb" role="img" aria-label="Time by phase"></div><div class="rsu-rc-pk"></div></div>
    <div class="rsu-rc-cut" aria-hidden="true"></div>
    <div class="rsu-rc-sec"><span class="rsu-rc-l">What changed</span><div class="rsu-rc-files"></div></div>
    <div class="rsu-rc-sec"><span class="rsu-rc-l">Needs you</span><div class="rsu-rc-nr"><span class="rsu-rc-nd"></span><span class="rsu-rc-nt">The yearly badge overlaps the price on a phone</span><button class="pill line sm rsu-rc-fix" type="button">Fix it</button></div></div>
    <div class="rsu-rc-acts"><button class="pill primary sm" type="button">${I('ext','xs')}Open changes</button><button class="pill ghost sm rsu-rc-undo" type="button"><span class="rsu-rc-hf" aria-hidden="true"></span><span class="lb">Hold to undo all</span></button></div>
  </div>`;
  function rsuReceipt(r, c){
    const root = $('.rsu-rc', r), stats = $('.rsu-rc-stats', r), pb = $('.rsu-rc-pb', r), pk = $('.rsu-rc-pk', r), files = $('.rsu-rc-files', r), undo = $('.rsu-rc-undo', r), lb = $('.lb', undo), fix = $('.rsu-rc-fix', r);
    const S = [['files', 6, v => Math.round(v)], ['steps', 14, v => Math.round(v)], ['tokens', 182, v => Math.round(v) + 'k'], ['cost', .84, v => '$' + v.toFixed(2)]];
    stats.innerHTML = S.map(s => `<span class="rsu-rc-st"><b class="num">0</b><span>${s[0]}</span></span>`).join('');
    $$('.rsu-rc-st b', r).forEach((b, i) => rsuCount(c, b, S[i][1], S[i][2], 300 + i * 90));
    const sum = RSU_PH.reduce((a, p) => a + p[1], 0);
    pb.innerHTML = RSU_PH.map(([n, m, k], i) => `<i style="--dm-w:${(m / sum * 100).toFixed(2)};--dm-k:var(--dm-ph-${k});animation-delay:${400 + i * 120}ms" data-tip="${n}, ${m.toFixed(1)} minutes"></i>`).join('');
    pk.innerHTML = RSU_PH.map(([n, m, k]) => `<span style="--dm-k:var(--dm-ph-${k})"><i></i>${n} <b>${m.toFixed(1)}m</b></span>`).join('');
    files.innerHTML = RSU_FILES.map(([f, a, x], i) => `<div class="rsu-rc-f"><code>${f}</code><span class="rsu-rc-ds" aria-hidden="true">${rsuBlocks(a, x).map((k, j) => `<i class="${k}" style="animation-delay:${600 + i * 120 + j * 40}ms"></i>`).join('')}</span><span class="n"><span class="a">+${a}</span> <span class="${x ? 'x' : ''}">−${x}</span></span></div>`).join('');
    stagger($$('.rsu-rc-f,.rsu-rc-nr,.rsu-rc-acts', r), 70, 500);
    $('.rsu-rc-cp', r).onclick = e => copied(e.currentTarget, RSU_TEXT, 'Summary copied');
    // the row keeps its height when its button goes, so the receipt never shrinks under the pointer
    fix.onclick = () => { const nr = $('.rsu-rc-nr', r); nr.style.minHeight = nr.offsetHeight + 'px'; fix.disabled = true; fix.innerHTML = '<span class="spin"></span>Fixing'; c.later(1300, () => { fix.remove(); nr.classList.add('ok'); swap($('.rsu-rc-nt', r), 'Badge moved above the price'); }); };
    // Undo all is pressed and held for a second; let go early and nothing happens. Once undone, a press redoes
    let t = 0, undone = false;
    const done = () => { undo.classList.remove('hold'); undone = !undone; root.classList.toggle('undone', undone); swap(lb, undone ? 'Redo' : 'Hold to undo all'); swap($('.rsu-rc-t', r), undone ? 'Changes undone' : 'Run complete'); swap($('.rsu-rc-s', r), undone ? '3 files restored' : 'Finished in 12m 40s'); };
    const start = () => { if (undone){ done(); return; } clearTimeout(t); undo.classList.add('hold'); swap(lb, 'Keep holding'); t = setTimeout(done, REDUCE ? 400 : 1000); };
    const stop = () => { if (!undo.classList.contains('hold')) return; clearTimeout(t); undo.classList.remove('hold'); swap(lb, 'Hold to undo all'); };
    c.on(undo, 'pointerdown', e => { if (e.button === 0) start(); });
    ['pointerup', 'pointerleave', 'pointercancel'].forEach(ev => c.on(undo, ev, stop));
    c.on(undo, 'keydown', e => { if ((e.key === ' ' || e.key === 'Enter') && !e.repeat){ e.preventDefault(); start(); } });
    c.on(undo, 'keyup', e => { if (e.key === ' ' || e.key === 'Enter') stop(); });
    c.offs.push(() => clearTimeout(t));
    undo.setAttribute('aria-label', 'Undo all, press and hold');
    // the person in the demo: reads the change phase, takes the fix, holds Undo all, then redoes
    c.story(async s => {
      await s.beat(5);
      await s.point($('.rsu-rc-pb i:nth-child(2)', r)); await s.beat(3); s.away();
      await s.tap(fix); s.away(); await s.beat(4);
      await s.point(undo, false); start(); await s.beat(3); s.away(); await s.beat(4);
      await s.tap(undo); s.away(); await s.beat(3);
    });
  }

  // Recap: the run told back as a timeline of the moments that mattered; hover one and the files it touched light up
  const RSU_RECAP = `<div class="rsu-rp">
    <div class="rsu-rp-h"><span class="rsu-rp-ok">${I('check')}</span><div class="rsu-rp-ht"><b>Pricing cards now use spacing tokens</b><span>Done in 12m 40s · $0.84</span></div></div>
    <div class="rsu-rp-files" aria-label="Files changed"></div>
    <div class="rsu-rp-tw"><i class="rsu-rp-rail" aria-hidden="true"></i><ol class="rsu-rp-tl" aria-label="What happened"></ol></div>
    <div class="rsu-rp-end">
      <div class="rsu-rp-pr">${BRAND.github}<div class="rsu-rp-prt"><b>#412 Use shared spacing tokens</b><span>feat/pricing-spacing into main</span></div><span class="tag ok">${I('check','xs')}Checks passed</span></div>
      <div class="rsu-rp-need"><span class="rsu-rp-ni">${I('warn','xs')}</span><span class="rsu-rp-nt">The yearly badge overlaps the price on a phone</span><button class="pill sm rsu-rp-fix" type="button">Review</button></div>
    </div>
  </div>`;
  function rsuRecap(r, c){
    const files = $('.rsu-rp-files', r), tl = $('.rsu-rp-tl', r), rail = $('.rsu-rp-rail', r), end = $('.rsu-rp-end', r), fix = $('.rsu-rp-fix', r);
    files.innerHTML = RSU_FILES.map(([f, a, x]) => `<span class="fchip rsu-rp-fc" data-f="${f}"><code>${f}</code><span class="n">+${a} −${x}</span></span>`).join('');
    // the moments that mattered, each with what it touched
    const M = [
      { app:'figma', t:'Read the plan cards in Figma', d:'Pricing v4, 3 frames', w:'0:40', f:[] },
      { ic:'file-text', t:'Found 9 spacing tokens', d:'tokens.css', w:'1:55', f:['tokens.css'] },
      { ic:'edit', t:'Swapped 14 values for tokens', d:'2 files, +33 −20', w:'5:10', f:['PricingCard.tsx', 'tokens.css'] },
      { ic:'term', t:'Tests failed, then passed', d:'2 failures fixed, 24 of 24', w:'9:30', f:['Pricing.test.tsx', 'PricingCard.tsx'], bad:true },
      { app:'github', t:'Opened pull request #412', d:'3 commits into main', w:'11:50', f:['PricingCard.tsx', 'tokens.css', 'Pricing.test.tsx'] },
      { app:'slack', t:'Posted in #design', d:'With before and after shots', w:'12:40', f:[] }
    ];
    tl.innerHTML = M.map(m => `<li class="rsu-rp-m${m.bad ? ' bad' : ''}" tabindex="0"><span class="rsu-rp-mi${m.app ? ' app' : ''}">${m.app ? BRAND[m.app] : I(m.bad ? 'refresh' : m.ic, 'xs')}</span><span class="rsu-rp-mt"><b>${m.t}</b><span>${m.d}</span></span><span class="rsu-rp-mw">${m.w}</span></li>`).join('');
    const rows = $$('.rsu-rp-m', tl);
    // a moment lights the files it touched
    const light = i => { $$('.rsu-rp-fc', files).forEach(fc => fc.classList.toggle('lit', i >= 0 && M[i].f.includes(fc.dataset.f))); rows.forEach((x, j) => x.classList.toggle('on', j === i)); };
    rows.forEach((x, i) => { ['pointerenter', 'focus'].forEach(ev => c.on(x, ev, () => light(i))); ['pointerleave', 'blur'].forEach(ev => c.on(x, ev, () => light(-1))); });
    c.on(tl, 'keydown', e => { const i = rows.indexOf(document.activeElement); if (i < 0) return; const j = e.key === 'ArrowDown' ? i + 1 : e.key === 'ArrowUp' ? i - 1 : null; if (j === null || !rows[j]) return; e.preventDefault(); rows[j].focus(); });
    // the note keeps its height when its button goes and its words get shorter, so the recap never shrinks under the pointer
    fix.onclick = () => { const nd = $('.rsu-rp-need', r); nd.style.minHeight = nd.offsetHeight + 'px'; fix.disabled = true; fix.innerHTML = '<span class="spin"></span>'; c.later(1200, () => { fix.remove(); nd.classList.add('ok'); $('.rsu-rp-ni', r).innerHTML = I('check','xs'); swap($('.rsu-rp-nt', r), 'Badge moved above the price'); }); };
    // the recap plays back once, a moment at a time, then the outcome
    c.run(async () => {
      await c.wait(400);
      for (let i = 0; i < rows.length; i++){ rows[i].classList.add('in'); rail.style.setProperty('--dm-p', ((i + .5) / rows.length).toFixed(3)); light(i); await c.wait(420); }
      light(-1); rail.style.setProperty('--dm-p', 1); end.classList.add('in');
    });
    // the person in the demo: hovers two moments to see what they touched, then reviews what needs them
    c.story(async s => {
      await s.until(() => end.classList.contains('in')); await s.beat(2);
      await s.point(rows[2], false); light(2); await s.beat(3);
      await s.point(rows[3], false); light(3); await s.beat(3); light(-1);
      await s.tap(fix); s.away(); await s.beat(5);
    });
  }

  // the switch: the design the card last showed (Classic to begin with) is drawn, and picking another mounts the card again
  // with it, so it plays from the start, entrance and demo; a key that picked it keeps the focus on the switch. Inside another
  // component (as in Agent harness), and in the registry, the code view and the component page (build.js leaves a
  // data-designs="card" switch out of them), it is the classic summary on its own
  const RSU_DS = { receipt:[RSU_RECEIPT, rsuReceipt], recap:[RSU_RECAP, rsuRecap] };
  DM.def('run-summary', (r, c, card) => {
    let dm = $(':scope>.rsu-dm', r);
    if (!dm) return classic(r, c, card);
    if (!c.card || r !== c.st){ dm.replaceWith(...$(':scope>.dm-main', dm).childNodes); return classic(r, c, card); }
    const v = RSU_DS[card._dv] ? card._dv : 'classic';
    if (v === 'classic') classic(r, c, card);
    // (the classic component may have drawn its icons into the stage again, so the switch is found afresh)
    dm = $(':scope>.rsu-dm', r);
    const main = $(':scope>.dm-main', dm), sg = $(':scope>.demo .seg2', dm);
    let tall = null, h = 0, wide = -1;
    // the card keeps the room the tallest design needs; this one sits with its own tallest moment in the middle of it, and
    // grows downwards from there. Its height is taken once at each width, so what it does never moves its top
    const fit = () => { const H = parseFloat(getComputedStyle(r).minHeight) || 0, w = r.clientWidth; if (w !== wide){ wide = w; h = tall ? tall() : main.offsetHeight; } dm.style.setProperty('--dm-dmy', Math.max(0, Math.floor((H - h) / 2)) + 'px'); };
    if (v !== 'classic'){ main.innerHTML = RSU_DS[v][0]; const t = RSU_DS[v][1](main, c); tall = typeof t === 'function' ? t : null; }
    // the classic summary is tallest once its numbers have counted up (on a phone they wrap onto a second line): a hidden
    // copy of it with them in is measured, then taken away
    else tall = () => { const a = $('.rsu', main); if (!a) return main.offsetHeight;
      const p = a.cloneNode(true); $$('.rsu-stats b[data-n]', p).forEach(b => { const n = b.dataset.n; b.textContent = (b.dataset.p || '') + (n.includes('.') ? (+n).toFixed(2) : n) + (b.dataset.u || ''); });
      p.style.cssText = 'position:absolute;left:0;right:0;top:0;visibility:hidden'; p.setAttribute('aria-hidden', 'true'); main.appendChild(p); const x = p.offsetHeight; p.remove(); return x; };
    $$('button', sg).forEach(b => b.setAttribute('aria-pressed', String(b.dataset.v === v)));
    seg(sg, k => {
      if (k === v) return;
      const kb = sg.contains(document.activeElement) && document.activeElement.matches(":focus-visible");
      card._dv = k; DM.mount(card);
      // it comes back once the new design has started, so it isn't taken for the visitor taking over the new demo
      if (kb) setTimeout(() => { const b = $(`.rsu-dm>.demo button[data-v="${k}"]`, card); if (b && (!document.activeElement || document.activeElement === document.body)) b.focus({ preventScroll:true }); }, 120);
    });
    const ro = new ResizeObserver(fit); ro.observe(r); c.offs.push(() => ro.disconnect());
  });
}

agent-lanes.css:
/* the card's three designs, picked in the switch under it: Classic (the component above, as it ships), Swimlanes and Crew, each filling the width and
   centred in the room kept for the tallest of them */
.dm.aln-dm{min-height:0}
.aln-dm>.dm-main>*{align-self:stretch}

/* Swimlanes: every agent's work on one clock. Each lane takes its agent's hue (--dm-c its text, --dm-cb its tint, --dm-cm its marks,
   3:1 on the surface): a soft tint for the lane, its steps as bars, and the hook that hands its work down to the next lane.
   A step still to come is a dashed outline; the one at work fills in stripes as the clock reaches it; a finished one is
   solid with its icon; a wait is hatched, with what it waits for. The playhead is grey with the time on it: drag it, click
   a lane or press the arrow keys to look back through the run. Lanes are one height, so the hooks are placed in CSS */
.aln-sw{--dm-lab:168px;--dm-rh:44px;--dm-gap:var(--dm-s-2);--dm-bh:24px;--dm-lt:7%;--dm-aln-sw-pb:#2a7bff;--dm-aln-sw-pm:#1fa66a;--dm-aln-sw-pl:#7a5af5;padding:var(--dm-s-3) var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .aln-sw{--dm-lt:12%;--dm-aln-sw-pb:var(--dm-pb);--dm-aln-sw-pm:var(--dm-pm);--dm-aln-sw-pl:var(--dm-pl)}}
:root[data-theme="dark"] .aln-sw{--dm-lt:12%;--dm-aln-sw-pb:var(--dm-pb);--dm-aln-sw-pm:var(--dm-pm);--dm-aln-sw-pl:var(--dm-pl)}
.aln-sw-h{display:flex;align-items:center;gap:var(--dm-s-4)}
.aln-sw-ht{flex:1;display:flex;flex-direction:column;min-width:0}
.aln-sw-ht b{font-weight:500}
.aln-sw-st{font-size:12.5px;color:var(--dm-muted)}
/* the key: how a step looks to come, at work, done and waiting, in grey since each lane has its own hue */
.aln-sw-key{display:flex;gap:var(--dm-s-3);font-size:11.5px;color:var(--dm-muted)}
.aln-sw-key span{display:inline-flex;align-items:center;gap:var(--dm-s-1)}
.aln-sw-key i{width:16px;height:8px;border-radius:var(--dm-r-xs)}
.aln-sw-key .next{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-fg2) 50%,transparent)}
.aln-sw-key .run{background:repeating-linear-gradient(135deg,color-mix(in srgb,var(--dm-fg2) 40%,var(--dm-surface)) 0 2px,color-mix(in srgb,var(--dm-fg2) 16%,var(--dm-surface)) 2px 4px)}
.aln-sw-key .done{background:var(--dm-fg2)}
.aln-sw-key .wait{background:repeating-linear-gradient(135deg,color-mix(in srgb,var(--dm-fg2) 30%,transparent) 0 1px,transparent 1px 3px)}
.aln-sw-grid{position:relative}
.aln-sw-ax{position:relative;height:24px;margin-left:var(--dm-lab);font-size:11px;color:var(--dm-muted)}
.aln-sw-ticks span{position:absolute;top:1px;transform:translateX(-50%)}
.aln-sw-ticks span:first-child{transform:none}.aln-sw-ticks span:last-child{transform:translateX(-100%)}
.aln-sw-rows{position:relative;display:flex;flex-direction:column;gap:var(--dm-gap)}
.aln-sw-row{display:grid;grid-template-columns:var(--dm-lab) minmax(0,1fr);align-items:center;height:var(--dm-rh)}
.aln-sw-who{display:flex;align-items:center;gap:var(--dm-s-2);min-width:0;padding-right:var(--dm-s-2)}
.aln-sw-av{width:28px;height:28px;border-radius:var(--dm-r-sm);display:grid;place-items:center;flex:none;background:var(--dm-cb);color:var(--dm-c)}
.aln-sw-av .i{width:14px;height:14px;color:inherit}
.aln-sw-row[data-s="work"] .aln-sw-av{animation:alnswbreathe 2s var(--dm-ease-io) infinite}
@keyframes alnswbreathe{50%{opacity:.6}}
/* the agent a hand-off reaches gives a small nod */
.aln-sw-row.got .aln-sw-av{animation:alnswgot .6s var(--dm-ease)}
@keyframes alnswgot{40%{transform:scale(1.15)}}
.aln-sw-wt{display:flex;flex-direction:column;min-width:0;font-size:12.5px;line-height:1.35}
.aln-sw-wt b{font-weight:500}
.aln-sw-wt span{font-size:11.5px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.aln-sw-row[data-s="work"] .aln-sw-wt span{color:var(--dm-fg2)}
/* the lane: its hue's soft tint, and a faint grey line every three seconds */
.aln-sw-lane{position:relative;height:100%;border-radius:var(--dm-r-in);background:linear-gradient(90deg,transparent 1px,color-mix(in srgb,var(--dm-line) 80%,transparent) 1px 2px,transparent 2px) -1px 0/25% 100%,color-mix(in srgb,var(--dm-cm) var(--dm-lt),var(--dm-surface))}
.aln-sw-b,.aln-sw-w{position:absolute;top:calc(50% - var(--dm-bh) / 2);height:var(--dm-bh);border-radius:var(--dm-r-sm);container-type:inline-size;transition:opacity .3s}
.aln-sw-b{border:1px dashed color-mix(in srgb,var(--dm-cm) 65%,transparent)}
.aln-sw-b.run,.aln-sw-b.done{border-color:transparent}
/* the stretch the clock has passed fills in, drawn with a clip so the bar is never laid out again */
.aln-sw-fl{position:absolute;inset:-1px;border-radius:inherit;overflow:hidden;background:color-mix(in srgb,var(--dm-cm) 20%,var(--dm-surface));clip-path:inset(0 calc((1 - var(--dm-f,0)) * 100%) 0 0);transition:clip-path .1s linear}
.aln-sw-fl i{position:absolute;top:0;bottom:0;left:-15px;right:0;display:none;background:repeating-linear-gradient(135deg,color-mix(in srgb,var(--dm-cm) 26%,transparent) 0 5px,transparent 5px 10px)}
.aln-sw-b.run .aln-sw-fl i{display:block;animation:alnswstripe .9s linear infinite}
.aln-sw.paused :is(.aln-sw-b.run .aln-sw-fl i,.aln-sw-av){animation-play-state:paused}
@keyframes alnswstripe{to{transform:translateX(14.14px)}}
.aln-sw-b.done .aln-sw-fl{background:var(--dm-cm)}
.aln-sw-fl .i{position:absolute;left:var(--dm-s-2);top:calc(50% - 6px);color:var(--dm-c)}
.aln-sw-b.done .aln-sw-fl .i{color:var(--dm-surface)}
@container (max-width:19px){.aln-sw-fl .i{display:none}}
/* a wait: hatched in the lane's hue, with what it waits for where there is room */
.aln-sw-w{background:repeating-linear-gradient(135deg,color-mix(in srgb,var(--dm-cm) 16%,transparent) 0 2px,transparent 2px 6px);clip-path:inset(0 calc((1 - var(--dm-f,0)) * 100%) 0 0);transition:clip-path .1s linear,opacity .3s}
.aln-sw-wl{position:absolute;inset:0 var(--dm-s-2);display:flex;align-items:center;gap:var(--dm-s-1);font-size:11px;color:var(--dm-fg2);white-space:nowrap;overflow:hidden}
.aln-sw-wl .i{flex:none;color:var(--dm-c)}
.aln-sw-wl span{overflow:hidden;text-overflow:ellipsis}
@container (max-width:180px){.aln-sw-wl span{display:none}}
@container (max-width:19px){.aln-sw-wl .i{display:none}}
/* looking back: what comes after the playhead steps back */
.aln-sw.scrub :is(.aln-sw-b,.aln-sw-w).after{opacity:.3}
/* a hand-off: a hook in the sender's hue from the foot of its last bar down into the start of the next lane's work, drawn
   down as it happens, and what was passed in a tag in the sender's tint */
.aln-sw-ho{position:absolute;z-index:2;left:calc(var(--dm-lab) + var(--dm-x0) * (100% - var(--dm-lab)));width:calc((var(--dm-x1) - var(--dm-x0)) * (100% - var(--dm-lab)));top:calc(var(--dm-from) * (var(--dm-rh) + var(--dm-gap)) + var(--dm-rh) / 2 + var(--dm-bh) / 2);height:calc((var(--dm-to) - var(--dm-from)) * (var(--dm-rh) + var(--dm-gap)) - var(--dm-bh) / 2);border-left:1.5px solid var(--dm-hc);border-bottom:1.5px solid var(--dm-hc);border-bottom-left-radius:5px;pointer-events:none;clip-path:inset(0 -10px 100% -4px);transition:clip-path .5s var(--dm-ease)}
.aln-sw-ho.on{clip-path:inset(0 -10px -8px -4px)}
.aln-sw-ho i{position:absolute;right:-6px;bottom:-4.75px;width:0;height:0;border-left:6px solid var(--dm-hc);border-top:4px solid transparent;border-bottom:4px solid transparent}
.aln-sw-tg{position:absolute;z-index:3;left:calc(var(--dm-lab) + var(--dm-x0) * (100% - var(--dm-lab)));top:calc(var(--dm-to) * (var(--dm-rh) + var(--dm-gap)) + var(--dm-rh) / 2 - 10px);background:color-mix(in srgb,var(--dm-c) 14%,var(--dm-surface));color:var(--dm-c);opacity:0;transform:translate(calc(-100% - 7px),4px);transition:opacity .3s,transform .45s var(--dm-ease);pointer-events:none}
.aln-sw-tg.on{opacity:1;transform:translate(calc(-100% - 7px),0)}
.aln-sw-tg .i{color:inherit}
/* the playhead: a grey line through the lanes and the time on a white tag, green once the run is done */
.aln-sw-ph{position:absolute;z-index:4;top:0;bottom:0;left:var(--dm-lab);right:0;pointer-events:none;outline:0}
.aln-sw-ph i{position:absolute;top:20px;bottom:-4px;left:-.75px;width:1.5px;background:var(--dm-fg2);transition:transform .1s linear}
.aln-sw-now{position:absolute;top:0;left:0;height:20px;padding:0 var(--dm-s-2);border-radius:var(--dm-r-tag);background:var(--dm-surface);box-shadow:var(--dm-shadow-pop),inset 0 0 0 1px color-mix(in srgb,var(--dm-line-strong) 50%,transparent);color:var(--dm-fg);font-size:11px;font-weight:500;line-height:20px;white-space:nowrap;pointer-events:auto;cursor:ew-resize;touch-action:none;transition:transform .1s linear}
@supports (corner-shape:squircle){.aln-sw-now{corner-shape:squircle;border-radius:var(--dm-r-tag-sq)}}
.aln-sw-ph.drag :is(i,.aln-sw-now){transition:none}
.aln-sw-ph:focus-visible .aln-sw-now{box-shadow:0 0 0 2px var(--dm-surface),0 0 0 4px var(--dm-focus)}
.aln-sw.fin .aln-sw-now{background:var(--dm-ok-bg);color:var(--dm-ok);box-shadow:none}
.aln-sw.fin .aln-sw-ph i{background:var(--dm-ok)}
.aln-sw-f{display:flex;align-items:center;gap:var(--dm-s-2);min-height:28px;padding-top:var(--dm-s-2);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12.5px;color:var(--dm-fg2)}
.aln-sw-say{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
@container (max-width:600px){.aln-sw-key{display:none}}
@container (max-width:460px){.aln-sw{--dm-lab:40px;padding:var(--dm-s-3)}.aln-sw-wt,.aln-sw-tg{display:none}}
:root:not([data-style="soft"]) .aln-sw-row[data-s="work"] .aln-sw-av:not(:where([data-style="soft"],[data-style="soft"] *)){animation:bpblink 1.1s steps(1,end) infinite}
:root:not([data-style="soft"]) .aln-sw-row.got .aln-sw-av:not(:where([data-style="soft"],[data-style="soft"] *)){animation:none}
:root:not([data-style="soft"]) .aln-sw-av:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-c) 35%,transparent)}
:root:not([data-style="soft"]) .aln-sw-b.run .aln-sw-fl i:not(:where([data-style="soft"],[data-style="soft"] *)){animation:alnswstripe 1.2s steps(4,end) infinite}
:root:not([data-style="soft"]) .aln-sw-ho:not(:where([data-style="soft"],[data-style="soft"] *)){border-left-width:1px;border-bottom-width:1px}
:root:not([data-style="soft"]) .aln-sw-ph i:not(:where([data-style="soft"],[data-style="soft"] *)){width:1px;left:-.5px}
:root:not([data-style="soft"]) .aln-sw-ho:not(:where([data-style="soft"],[data-style="soft"] *)),:root:not([data-style="soft"]) .aln-sw-tg:not(:where([data-style="soft"],[data-style="soft"] *)){transition-timing-function:steps(4,end)}

/* Crew: a card per agent, each on its own clock, so pausing one or steering it leaves the others running. Its avatar is in
   the avatar colours. Its progress is a thin line through a dot for each step: in the accent while it works, a mid grey
   while it waits or is paused, green once it is done. Between two cards, what the one hands the other */
.aln-cw{display:flex;flex-direction:column;gap:var(--dm-s-3)}
.aln-cw-h{display:flex;align-items:center;gap:var(--dm-s-2);padding:0 4px}
.aln-cw-ic{display:grid;color:var(--dm-fg2)}
.aln-cw-ic .i{color:inherit}
.aln-cw-tt{flex:1;font-weight:500}
.aln-cw-tot{font-size:13px;color:var(--dm-fg2)}
.aln-cw-list{display:flex;flex-direction:column}
.aln-cw-c{position:relative;display:flex;flex-direction:column;padding:var(--dm-s-3);border-radius:var(--dm-r-card);background:var(--dm-surface);box-shadow:var(--dm-shadow);transition:opacity .3s}
.aln-cw-c[data-s="hold"]{opacity:.8}
.aln-cw-top{display:flex;align-items:center;gap:var(--dm-s-3)}
.aln-cw-av{width:28px;height:28px;border-radius:var(--dm-r-sm);display:grid;place-items:center;flex:none;background:var(--dm-a);color:var(--dm-ai)}
.aln-cw-av .i{width:14px;height:14px;stroke-width:1.9;color:inherit}
.aln-cw-c[data-s="work"] .aln-cw-av{animation:alnswbreathe 2s var(--dm-ease-io) infinite}
.aln-cw-tx{flex:1;min-width:0;display:flex;flex-direction:column}
.aln-cw-tx b{font-weight:500;font-size:13px}
.aln-cw-tx span{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.aln-cw-c[data-s="work"] .aln-cw-tx span{color:var(--dm-fg2)}
.aln-cw-tag .spin{width:9px;height:9px}
.aln-cw-acts{display:flex;gap:var(--dm-s-1)}
.aln-cw-acts .ib{width:28px;height:28px}
.aln-cw-acts .ib[aria-pressed="true"],.aln-cw-acts .ib[aria-expanded="true"]{background:var(--dm-hover);color:var(--dm-fg)}
.aln-cw-meter{display:flex;align-items:center;gap:var(--dm-s-3);margin-top:var(--dm-s-3)}
/* the note field and the note it leaves keep their gap inside them, so a shut field takes no room */
.aln-cw-c>.fold .aln-cw-steer{margin-top:var(--dm-s-3)}
.aln-cw-nts:not(:empty){margin-top:var(--dm-s-2)}
.aln-cw-tr{position:relative;flex:1;min-width:64px;height:12px;display:grid;grid-template-columns:repeat(var(--dm-n),minmax(0,1fr));align-items:center;--dm-cwf:color-mix(in srgb,var(--dm-muted) 80%,var(--dm-surface))}
.aln-cw-c[data-s="work"] .aln-cw-tr{--dm-cwf:var(--dm-accent-mark,var(--dm-accent))}
.aln-cw-c[data-s="done"] .aln-cw-tr{--dm-cwf:var(--dm-ok)}
.aln-cw-ln{position:absolute;left:0;right:5px;top:5px;height:2px;background:var(--dm-line);overflow:hidden}
.aln-cw-ln i{position:absolute;inset:0;background:var(--dm-cwf);transform-origin:left;transform:scaleX(var(--dm-p,0));transition:transform .2s linear,background .3s}
.aln-cw-tr b{justify-self:end;position:relative;width:10px;height:10px;border-radius:50%;background:var(--dm-surface);box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--dm-muted) 80%,var(--dm-surface));transition:background .3s,box-shadow .3s}
.aln-cw-tr b.done{background:var(--dm-cwf);box-shadow:none}
.aln-cw-tr b.now{box-shadow:inset 0 0 0 2px var(--dm-cwf)}
.aln-cw-c[data-s="work"] .aln-cw-tr b.now{animation:alncwnow 1.6s var(--dm-ease-io) infinite}
@keyframes alncwnow{50%{transform:scale(1.25)}}
.aln-cw-num{display:flex;gap:var(--dm-s-2);font-size:11.5px;color:var(--dm-muted);font-variant-numeric:tabular-nums;white-space:nowrap}
.aln-cw-num b{font-weight:500;color:var(--dm-fg2)}
/* steering one agent: a note it reads before its next step */
.aln-cw-steer{display:flex;align-items:center;gap:var(--dm-s-1);padding:var(--dm-s-1) var(--dm-s-1) var(--dm-s-1) var(--dm-s-3);border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent)}
.aln-cw-steer:has(input:focus){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
@supports (corner-shape:squircle){.aln-cw-steer{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.aln-cw-steer input{flex:1;min-width:0;height:28px;border:0;outline:0;background:none;font:inherit;font-size:12.5px;color:var(--dm-fg)}
.aln-cw-steer input::placeholder{color:var(--dm-muted)}
.aln-cw-note{display:flex;align-items:center;gap:var(--dm-s-2);font-size:12px;color:var(--dm-fg2);animation:alncwin .45s var(--dm-ease)}
.aln-cw-note .i{color:var(--dm-ok)}
@keyframes alncwin{from{opacity:0;transform:translateY(6px)}}
/* a hand-off between two cards: the sender, what it passes in the site's grey tag, and the receiver, joined by grey lines,
   dashed until the work is passed, then solid with the tag ticked */
.aln-cw-ho{display:flex;align-items:center;justify-content:center;gap:var(--dm-s-2);height:32px;font-size:11.5px;color:var(--dm-muted)}
.aln-cw-ho .ln{width:22px;border-top:1.5px dashed var(--dm-rail)}
.aln-cw-ho.on .ln{border-top-style:solid;border-top-color:var(--dm-faint)}
.aln-cw-ho.on .tag{animation:alncwgot .5s var(--dm-ease)}
@keyframes alncwgot{40%{transform:scale(1.1)}}
@container (max-width:420px){.aln-cw-tkn{display:none}}
:root:not([data-style="soft"]) .aln-cw-c[data-s="work"] .aln-cw-av:not(:where([data-style="soft"],[data-style="soft"] *)){animation:bpblink 1.1s steps(1,end) infinite}
:root:not([data-style="soft"]) .aln-cw-ln i:not(:where([data-style="soft"],[data-style="soft"] *)){transition:transform .3s steps(3,end),background .2s}
:root:not([data-style="soft"]) .aln-cw-c[data-s="work"] .aln-cw-tr b.now:not(:where([data-style="soft"],[data-style="soft"] *)){animation:bpblink 1.1s steps(1,end) infinite}
