agent-lanes.js:
/* ---------- Agent lanes designs ---------- */
{
  const classic = DM.defs['agent-lanes'];
  // the run Swimlanes and Crew play: three agents on one clock, in seconds. Each does its steps; the designer and the
  // reviewer start on their own work, then wait for the hand-off from the one before them. t is the agent's palette slot (its
  // lane's hue), av its avatar colour, and each step's ic the icon on its bar
  const ALN_RUN = () => [
    { n:'Researcher', ic:'search', t:'pb', av:'b', cost:.08, steps:[{ t:'Read 5 pricing pages', s:0, d:1.6, ic:'globe' }, { t:'Compared plans and limits', s:1.6, d:1.4, ic:'layers' }, { t:'Wrote the brief', s:3, d:1.2, ic:'file-text' }] },
    { n:'Designer', ic:'palette', t:'pl', av:'l', cost:.21, waitFrom:2.3, waitTo:4.4, waitFor:'the brief', steps:[{ t:'Set up Pricing v5', s:.8, d:1.5, ic:'figma' }, { t:'Laid out the plan cards', s:4.4, d:2.2, ic:'grid' }, { t:'Set type and spacing', s:6.6, d:1.4, ic:'sliders' }, { t:'Exported 4 frames', s:8, d:.8, ic:'upload' }] },
    { n:'Reviewer', ic:'eye', t:'pm', av:'m', cost:.06, waitFrom:3.2, waitTo:9, waitFor:'the frames', steps:[{ t:'Read last month’s copy', s:1.6, d:1.6, ic:'book' }, { t:'Checked contrast', s:9, d:1.4, ic:'eye' }, { t:'Fixed 2 lines of copy', s:10.4, d:1, ic:'edit' }, { t:'Approved the page', s:11.4, d:.6, ic:'check' }] }
  ];
  // the hand-offs: at its time the sender passes its work, which the receiver picks up at got
  const ALN_HAND = [{ from:0, to:1, at:4.2, got:4.4, what:'brief' }, { from:1, to:2, at:8.8, got:9, what:'4 frames' }];
  const ALN_END = 12;
  const alnClock = t => '0:' + String(Math.floor(t)).padStart(2, '0');
  const alnLc = s => s.charAt(0).toLowerCase() + s.slice(1);
  // what an agent is doing at a moment: a step, waiting, idle or done
  // (times are compared a hair early, so a clock of tenths lands on a step's end exactly)
  function alnAt(a, t){
    t += 1e-6;
    const st = a.steps.find(x => t >= x.s && t < x.s + x.d); if (st) return { s:'work', t:st.t, step:st };
    if (a.waitFrom !== undefined && t >= a.waitFrom && t < a.waitTo) return { s:'wait', t:'Waiting for ' + a.waitFor };
    const last = a.steps[a.steps.length - 1]; if (t >= last.s + last.d) return { s:'done', t:'Done, ' + alnLc(last.t) };
    if (t < a.steps[0].s) return { s:'idle', t:'Starts soon' };
    return { s:'idle', t:'Between steps' };
  }

  const alnSwTpl = () => `<div class="aln-sw panel keep">
    <div class="aln-sw-h"><div class="aln-sw-ht"><b class="aln-sw-tt">3 agents working</b><span class="aln-sw-st num">0:00 of 0:12</span></div><span class="aln-sw-key" aria-hidden="true"><span><i class="next"></i>Next</span><span><i class="run"></i>Working</span><span><i class="done"></i>Done</span><span><i class="wait"></i>Waiting</span></span><button class="pill soft sm aln-sw-pause" type="button">${I('pause','xs')}Pause</button></div>
    <div class="aln-sw-grid">
      <div class="aln-sw-ax num" aria-hidden="true"><span class="aln-sw-ticks"></span></div>
      <div class="aln-sw-rows"></div>
      <div class="aln-sw-ph" role="slider" tabindex="0" aria-label="Time in the run" aria-valuemin="0" aria-valuemax="12" aria-valuenow="0" aria-valuetext="0 seconds"><i></i><span class="aln-sw-now num">0:00</span></div>
    </div>
    <div class="aln-sw-f"><span class="aln-sw-say" aria-live="polite">Researcher starts on the pricing pages</span><button class="pill soft sm aln-sw-live" type="button" hidden>Back to now</button></div>
  </div>`;
  // Swimlanes: the clock ticks ten times a second while the demo plays and nobody has paused it. Bars reveal with a clip and
  // the playhead moves with a transform; text changes only when it says something new
  function alnSwim(r, c){
    const A = ALN_RUN(), root = $('.aln-sw', r), rows = $('.aln-sw-rows', r), ph = $('.aln-sw-ph', r), line = $('i', ph), now = $('.aln-sw-now', r), st = $('.aln-sw-st', r), say = $('.aln-sw-say', r), live = $('.aln-sw-live', r), pb = $('.aln-sw-pause', r), tt = $('.aln-sw-tt', r);
    $('.aln-sw-ticks', r).innerHTML = [0, 3, 6, 9, 12].map(t => `<span style="left:${t / ALN_END * 100}%">${t}s</span>`).join('');
    const pct = v => (v / ALN_END * 100).toFixed(3) + '%', clamp = v => Math.max(0, Math.min(1, Math.round(v * 1e4) / 1e4));
    A.forEach(a => {
      a.el = html(`<div class="aln-sw-row" data-s="idle" style="--dm-c:var(--dm-${a.t});--dm-cb:var(--dm-${a.t}-bg);--dm-cm:var(--dm-aln-sw-${a.t},var(--dm-${a.t}))"><div class="aln-sw-who"><span class="aln-sw-av" aria-hidden="true">${I(a.ic)}</span><span class="aln-sw-wt"><b>${a.n}</b><span>Starts soon</span></span></div><div class="aln-sw-lane"></div></div>`);
      const lane = $('.aln-sw-lane', a.el);
      if (a.waitFrom !== undefined){ a.w = html(`<span class="aln-sw-w" style="left:${pct(a.waitFrom)};width:calc(${pct(a.waitTo - a.waitFrom)} - 2px)"><span class="aln-sw-wl">${I('clock','xs')}<span>Waiting for ${a.waitFor}</span></span></span>`); lane.appendChild(a.w); }
      a.steps.forEach(x => { x.el = html(`<span class="aln-sw-b" style="left:${pct(x.s)};width:calc(${pct(x.d)} - 2px)" data-tip="${a.n}: ${x.t}, ${x.d.toFixed(1)}s"><span class="aln-sw-fl"><i></i>${I(x.ic,'xs')}</span></span>`); lane.appendChild(x.el); });
      rows.appendChild(a.el);
    });
    stagger($$('.aln-sw-row', r), 60);
    // the hand-offs, each a hook in its sender's hue and what was passed, placed by the lanes they join and the times
    const hos = ALN_HAND.map(h => { const a = A[h.from];
      const el = html(`<span class="aln-sw-ho" style="--dm-hc:var(--dm-aln-sw-${a.t},var(--dm-${a.t}));--dm-from:${h.from};--dm-to:${h.to};--dm-x0:${h.at / ALN_END};--dm-x1:${h.got / ALN_END}" aria-hidden="true"><i></i></span>`);
      const tg = html(`<span class="tag aln-sw-tg" style="--dm-c:var(--dm-${a.t});--dm-to:${h.to};--dm-x0:${h.at / ALN_END}" aria-hidden="true">${I('file-text','xs')}${h.what}</span>`);
      rows.append(el, tg); return { ...h, el, tg }; });
    // the lane's width is read when it changes size, never while the clock runs
    let W = 0, CW = 0, T = 0, V = null, paused = false, fin = false, said = '';
    const lay = () => { W = $('.aln-sw-lane', A[0].el).clientWidth; CW = now.offsetWidth; paint(); };
    const ro = new ResizeObserver(lay); ro.observe(rows); c.offs.push(() => ro.disconnect());
    // the run as it stands: bars fill up to now (T); the playhead sits at now, or where you took it (V)
    function paint(){
      const v = V === null ? T : V;
      root.classList.toggle('scrub', V !== null);
      A.forEach(a => {
        a.steps.forEach(x => { const f = clamp((T - x.s) / x.d), k = f >= 1 ? 'done' : f > 0 ? 'run' : '';
          if (x.f !== f){ x.f = f; x.el.style.setProperty('--dm-f', f.toFixed(4)); }
          if (x.k !== k){ x.k = k; x.el.classList.toggle('run', k === 'run'); x.el.classList.toggle('done', k === 'done'); }
          const af = x.s > v; if (x.af !== af){ x.af = af; x.el.classList.toggle('after', af); } });
        if (a.w){ const f = clamp((T - a.waitFrom) / (a.waitTo - a.waitFrom)); if (a.wf !== f){ a.wf = f; a.w.style.setProperty('--dm-f', f.toFixed(4)); } a.w.classList.toggle('after', a.waitFrom > v); }
        const at = alnAt(a, v); if (a.s !== at.s){ a.s = at.s; a.el.dataset.s = at.s; } if (a.say !== at.t){ a.say = at.t; $('.aln-sw-wt span', a.el).textContent = at.t; }
      });
      hos.forEach(h => { const on = T >= h.at && v >= h.at; if (h.on !== on){ h.on = on; h.el.classList.toggle('on', on); h.tg.classList.toggle('on', on); } });
      const x = v / ALN_END * W; line.style.transform = `translateX(${x.toFixed(1)}px)`;
      now.style.transform = `translateX(${Math.max(-6, Math.min(W - CW + 6, x - CW / 2)).toFixed(1)}px)`;
    }
    function text(){
      const v = V === null ? T : V, put = (el, s) => { if (el.textContent !== s) el.textContent = s; };
      put(now, alnClock(v)); put(st, paused ? `Paused at ${alnClock(T)}` : fin ? 'Done in 0:12, with 2 hand-offs' : `${alnClock(T)} of 0:12`);
      ph.setAttribute('aria-valuenow', v.toFixed(1)); ph.setAttribute('aria-valuetext', `${v.toFixed(1)} seconds: ${A.map(a => a.n + ', ' + alnLc(alnAt(a, v).t)).join('; ')}`);
      const busy = A.filter(a => alnAt(a, v).s === 'work');
      const ln = V !== null ? `At ${alnClock(v)}: ${busy.length ? busy.map(a => `${a.n} ${alnLc(alnAt(a, v).t)}`).join(', ') : 'between steps'}` : fin ? 'All three finished in 12 seconds, with 2 hand-offs' : busy.length ? busy.map(a => `${a.n}: ${alnLc(alnAt(a, v).t)}`).join(' · ') : said;
      if (ln !== said){ said = ln; say.textContent = ln; }
    }
    // the agent a hand-off reaches nods as it gets the work
    const fire = () => hos.forEach(h => { if (T >= h.at && !h.fired){ h.fired = true; const b = A[h.to].el; b.classList.add('got'); c.later(650, () => b.classList.remove('got')); } });
    const iv = c.every(100, () => {
      if (paused || fin) return;
      T = Math.min(ALN_END, Math.round(T * 10 + 1) / 10); paint(); text(); fire();
      if (T >= ALN_END){ fin = true; clearInterval(iv); root.classList.add('fin'); swap(tt, 'All 3 agents finished'); pb.hidden = true; text(); }
    });
    pb.onclick = () => { paused = !paused; root.classList.toggle('paused', paused); pb.innerHTML = I(paused ? 'play' : 'pause','xs') + (paused ? 'Resume' : 'Pause'); swap(tt, paused ? 'All agents paused' : '3 agents working'); text(); };
    // dragging the playhead's time, clicking a lane, or the arrow keys on the playhead look back through the run; Back to
    // now follows the run again
    const seek = v => { v = Math.max(0, Math.min(T, v)); V = v >= T - .05 ? null : v; live.hidden = V === null; paint(); text(); };
    live.onclick = () => seek(T);
    const laneLeft = () => $('.aln-sw-lane', A[0].el).getBoundingClientRect().left;
    let drag = false, left = 0;
    c.on(now, 'pointerdown', e => { drag = true; ph.classList.add('drag'); left = laneLeft(); now.setPointerCapture(e.pointerId); e.preventDefault(); ph.focus({ preventScroll:true }); });
    c.on(now, 'pointermove', e => { if (drag && W) seek((e.clientX - left) / W * ALN_END); });
    const up = () => { drag = false; ph.classList.remove('drag'); }; c.on(now, 'pointerup', up); c.on(now, 'pointercancel', up);
    c.on(rows, 'pointerdown', e => { if (e.target.closest('.aln-sw-lane') && W) seek((e.clientX - laneLeft()) / W * ALN_END); });
    c.on(ph, 'keydown', e => { const v = V === null ? T : V, k = e.key; const to = k === 'ArrowLeft' || k === 'ArrowDown' ? v - .5 : k === 'ArrowRight' || k === 'ArrowUp' ? v + .5 : k === 'Home' ? 0 : k === 'End' ? T : null; if (to === null) return; e.preventDefault(); seek(to); });
    paint(); text();
    // the story: once the run is done, someone takes the playhead back through it, then back to now
    c.story(async s => {
      await s.until(() => fin); await s.beat(2);
      await s.point(now, false); seek(3.5); await s.point(now, false); await s.beat(1);
      seek(5.5); await s.point(now, false); await s.beat(3);
      seek(9.6); await s.point(now, false); await s.beat(3); s.away();
      await s.tap(live); s.away(); await s.beat(3);
    });
  }

  const alnCrewTpl = () => `<div class="aln-cw"><div class="aln-cw-h"><span class="aln-cw-ic">${I('users')}</span><b class="aln-cw-tt">3 agents working</b><span class="aln-cw-tot num">$0.00</span></div><div class="aln-cw-list"></div></div>`;
  // Crew: each agent keeps its own clock, which stops while you pause it, and a hand-off waits for the agent before it
  function alnCrew(r, c){
    const A = ALN_RUN(), H = ALN_HAND.map(h => ({ ...h })), list = $('.aln-cw-list', r), tot = $('.aln-cw-tot', r), tt = $('.aln-cw-tt', r);
    let fin = false;
    A.forEach((a, i) => {
      a.held = false; a.tk = 0; a.spent = 0; a.t = 0; const N = a.steps.length;
      a.el = html(`<div class="aln-cw-c" data-s="idle" style="--dm-a:var(--dm-av-${a.av});--dm-ai:var(--dm-av-${a.av}-ink)"><div class="aln-cw-top"><span class="aln-cw-av" aria-hidden="true">${I(a.ic)}</span><span class="aln-cw-tx"><b>${a.n}</b><span>Starts soon</span></span><span class="tag aln-cw-tag">Up next</span><span class="aln-cw-acts"><button class="ib aln-cw-hold" type="button" aria-pressed="false" aria-label="Pause ${a.n}" data-tip="Pause this agent">${I('pause','xs')}</button><button class="ib aln-cw-sb" type="button" aria-expanded="false" aria-label="Steer ${a.n}" data-tip="Steer">${I('wand','xs')}</button></span></div><div class="aln-cw-meter"><span class="aln-cw-tr" role="progressbar" aria-label="${a.n}’s steps" aria-valuemin="0" aria-valuemax="${N}" aria-valuenow="0" style="--dm-n:${N}"><span class="aln-cw-ln"><i></i></span>${'<b></b>'.repeat(N)}</span><span class="aln-cw-num"><span><b class="aln-cw-sn">0</b> of ${N} steps</span><span class="aln-cw-tkn"><b class="aln-cw-tk">0</b> tokens</span><b class="aln-cw-cs">$0.00</b></span></div><div class="fold shut"><div><form class="aln-cw-steer"><input aria-label="A note for the ${a.n.toLowerCase()}" placeholder="Tell the ${a.n.toLowerCase()} what to change"><button class="ib" type="submit" aria-label="Send" data-tip="Send">${I('send','xs')}</button></form></div></div><div class="aln-cw-nts"></div></div>`);
      list.appendChild(a.el);
      a.tr = $('.aln-cw-tr', a.el); a.ln = $('.aln-cw-ln i', a.el); a.dots = $$('.aln-cw-tr b', a.el); a.sn = $('.aln-cw-sn', a.el); a.tkEl = $('.aln-cw-tk', a.el); a.csEl = $('.aln-cw-cs', a.el);
      if (i < A.length - 1){ const h = H[i]; h.el = html(`<div class="aln-cw-ho"><span>${a.n}</span><span class="ln"></span><span class="tag">${I('clock','xs')}${h.what}</span><span class="ln"></span><span>${A[i + 1].n}</span></div>`); list.appendChild(h.el); }
      const hold = $('.aln-cw-hold', a.el), sb = $('.aln-cw-sb', a.el), fold = $('.fold', a.el), form = $('.aln-cw-steer', a.el), inp = $('input', form);
      fold.inert = true;
      hold.onclick = () => { a.held = !a.held; hold.setAttribute('aria-pressed', String(a.held)); hold.innerHTML = I(a.held ? 'play' : 'pause','xs'); hold.dataset.tip = a.held ? 'Resume this agent' : 'Pause this agent'; hold.setAttribute('aria-label', (a.held ? 'Resume ' : 'Pause ') + a.n); paint(a); };
      // the note's field takes the focus only when you open it yourself; the demo never moves your focus
      sb.onclick = e => { const on = sb.getAttribute('aria-expanded') !== 'true'; sb.setAttribute('aria-expanded', String(on)); fold.classList.toggle('shut', !on); fold.inert = !on; if (on && e.isTrusted) requestAnimationFrame(() => inp.focus({ preventScroll:true })); };
      // the note shows once its field has shut, so the card never holds both at once
      form.onsubmit = e => { e.preventDefault(); const v = inp.value.trim(); if (!v) return; inp.value = ''; sb.click(); if (form.contains(document.activeElement)) sb.focus({ preventScroll:true });
        setTimeout(() => { if (a.el.isConnected) $('.aln-cw-nts', a.el).replaceChildren(html(`<div class="aln-cw-note">${I('check','xs')}<span>Got it: “${v.replace(/&/g, '&amp;').replace(/</g, '&lt;')}”, before the next step</span></div>`)); }, REDUCE ? 0 : 460); };
    });
    function paint(a){
      const at = alnAt(a, a.t), s = a.held && at.s !== 'done' ? 'hold' : at.s;
      if (a.s !== s){ a.s = s; a.el.dataset.s = s; const tg = $('.aln-cw-tag', a.el);
        tg.className = 'tag aln-cw-tag' + (s === 'done' ? ' ok' : s === 'hold' ? ' warn' : '');
        tg.innerHTML = s === 'work' ? '<span class="spin"></span>Working' : s === 'wait' ? 'Waiting' : s === 'done' ? I('check','xs') + 'Done' : s === 'hold' ? 'Paused' : 'Up next'; }
      const ln = s === 'hold' ? 'Paused by you' : at.t; if (a.say !== ln){ a.say = ln; const sp = $('.aln-cw-tx span', a.el); sp.className = s === 'work' ? 'shim' : ''; sp.textContent = ln; }
      // the line through the steps: up to each finished step's dot, and on towards the next as the step at work goes
      const N = a.steps.length, t = a.t + 1e-6, done = a.steps.filter(x => t >= x.s + x.d).length, cur = a.steps.find(x => t >= x.s && t < x.s + x.d);
      const p = Math.min(1, Math.round((done + (cur ? (a.t - cur.s) / cur.d : 0)) / N * 1e3) / 1e3);
      if (a.p !== p){ a.p = p; a.ln.style.transform = `scaleX(${p.toFixed(3)})`; }
      if (a.done !== done){ a.done = done; a.dots.forEach((d, k) => { d.classList.toggle('done', k < done); d.classList.toggle('now', k === done); }); a.sn.textContent = done; a.tr.setAttribute('aria-valuenow', done); }
    }
    c.every(100, () => {
      let spent = 0;
      A.forEach((a, i) => {
        const prev = H[i - 1];
        const blocked = prev && a.t >= (a.waitFrom ?? 99) && A[prev.from].t < prev.at;
        // once the hand-off has come, the wait is over at once
        if (!blocked && prev && a.t >= a.waitFrom && a.t < a.waitTo) a.t = a.waitTo;
        if (!a.held && !blocked && a.t < ALN_END) a.t = Math.min(ALN_END, Math.round(a.t * 10 + 1) / 10);
        if (alnAt(a, a.t).s === 'work' && !a.held){ a.tk += 40 + Math.random() * 90; a.spent += a.cost / 50; }
        spent += a.spent; paint(a);
        const tk = Math.round(a.tk).toLocaleString('en-US'), cs = '$' + a.spent.toFixed(2);
        if (a.tkEl.textContent !== tk) a.tkEl.textContent = tk; if (a.csEl.textContent !== cs) a.csEl.textContent = cs;
      });
      H.forEach(h => { if (!h.on && A[h.from].t >= h.at){ h.on = true; h.el.classList.add('on'); const tg = $('.tag', h.el); tg.className = 'tag ok'; tg.innerHTML = I('check','xs') + h.what; } });
      const ts = '$' + spent.toFixed(2); if (tot.textContent !== ts) tot.textContent = ts;
      if (!fin && A.every(a => a.t >= ALN_END)){ fin = true; swap(tt, 'All 3 agents finished'); $('.aln-cw-ic', r).innerHTML = I('ok'); }
    });
    A.forEach(paint);
    // the story: someone steers the designer while it works, then pauses the reviewer for a moment
    c.story(async s => {
      await s.until(() => A[1].s === 'work' && A[1].t > 5); await s.beat(1);
      await s.tap($('.aln-cw-sb', A[1].el)); s.away();
      await s.type($('input', A[1].el), 'Make the Pro card stand out', { n:.07, keep:true });
      await s.beat(1); await s.tap($('.aln-cw-steer .ib', A[1].el)); s.away();
      await s.until(() => A[2].s === 'work'); await s.beat(2);
      await s.tap($('.aln-cw-hold', A[2].el)); s.away(); await s.beat(4);
      await s.tap($('.aln-cw-hold', A[2].el)); s.away();
      await s.until(() => fin); await s.beat(4);
    });
  }
  // the switch: the design the card last showed (Classic to begin with) is drawn, and picking another starts the card
  // again with it, as Animate does (on designme.dev through the card's own replay, so its footer tabs follow)
  DM.def('agent-lanes', (r, c, card) => {
    const dm0 = $(':scope>.aln-dm', r);
    if (!dm0) return classic(r, c, card);
    // placed inside another component (as in Agent harness, where the card's own stage is not there), it is Classic, as it was
    if (!c.card){ dm0.replaceWith(...$(':scope>.dm-main', dm0).childNodes); return classic(r, c, card); }
    const D = { swimlanes:[alnSwim, alnSwTpl], crew:[alnCrew, alnCrewTpl] }, dv = D[c.card._dv] ? c.card._dv : 'classic';
    if (dv === 'classic') classic(r, c, card);
    else { $(':scope>.aln-dm>.dm-main', r).innerHTML = D[dv][1](); D[dv][0](r, c); }
    const sg = $(':scope>.aln-dm>.demo .seg2', r); if (!sg) return;
    $$('button', sg).forEach(b => b.setAttribute('aria-pressed', String(b.dataset.v === dv)));
    seg(sg, v => { if (v === dv || !(v === 'classic' || D[v])) return; c.card._dv = v; if (window.V2 && c.card.dataset.v2) window.V2.replay(c.card); else DM.mount(c.card); });
  });
}

thread-panel.css:
/* the homepage card's design switch: Classic is the component above, and Deck and Focus are two directions under review,
   each under .thp[data-d]. A thread belongs to an agent, shown by its avatar in the avatar colours (--dm-a, its ink --dm-ai), and
   the rest is grey. What an agent is doing shows as a dot on its avatar: green and blinking while it works, amber while it
   waits for you */
.dm.thp-dm>.dm-main{align-items:stretch}
.thp[data-d]{height:auto;overflow:visible}
.thp[data-d] .tpx-av{position:relative;width:28px;height:28px;border-radius:calc(9px * var(--dm-rk));display:grid;place-items:center;flex:none;background:var(--dm-a);color:var(--dm-ai)}
.thp[data-d] .tpx-av .i{width:14px;height:14px;stroke-width:1.9;color:inherit}
.thp[data-d] .tpx-st{position:absolute;right:-3px;bottom:-3px;width:10px;height:10px;border-radius:50%;box-shadow:0 0 0 2px var(--dm-surface);opacity:0;transform:scale(.4);transition:opacity .3s,transform .4s var(--dm-ease)}
.thp[data-d] .tpx-av[data-s="ask"] .tpx-st{opacity:1;transform:none;background:var(--dm-warn-mark)}
.thp[data-d] .tpx-av[data-s="work"] .tpx-st{opacity:1;transform:none;background:var(--dm-ok-mark);animation:tpxblink 1.4s var(--dm-ease-io) infinite}
@keyframes tpxblink{50%{opacity:.35}}
/* the conversation */
.thp[data-d] .tpx-scroll{overflow-y:auto;overscroll-behavior:contain;scrollbar-width:none;-webkit-mask-image:linear-gradient(transparent,#000 16px,#000 calc(100% - 8px),transparent);mask-image:linear-gradient(transparent,#000 16px,#000 calc(100% - 8px),transparent)}
.thp[data-d] .tpx-scroll::-webkit-scrollbar{display:none}
.thp[data-d] .tpx-a{display:flex;flex-direction:column;gap:6px;max-width:100%;font-size:13.5px;line-height:1.6;color:var(--dm-fg)}
.thp[data-d] .tpx-src{display:flex;flex-wrap:wrap;gap:5px}
.thp[data-d] .tpx-src .fchip .brand{width:12px;height:12px}
.thp[data-d] .tpx-who{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--dm-muted)}
.thp[data-d] .tpx-who .tpx-av{width:18px;height:18px;border-radius:calc(6px * var(--dm-rk))}
.thp[data-d] .tpx-who .tpx-av .i{width:10px;height:10px}
/* an answer the agent is still writing: three dots, then the words as they come */
.thp[data-d] .tpx-dots{display:inline-flex;gap:4px;align-items:center;height:18px}
.thp[data-d] .tpx-dots i{width:6px;height:6px;border-radius:50%;background:var(--dm-muted);animation:tpxdot 1.1s var(--dm-ease-io) infinite}
.thp[data-d] .tpx-dots i:nth-child(2){animation-delay:.15s}.thp[data-d] .tpx-dots i:nth-child(3){animation-delay:.3s}
@keyframes tpxdot{0%,60%,100%{transform:none;opacity:.45}30%{transform:translateY(-4px);opacity:1}}
.thp[data-d] .tpx-caret{display:inline-block;width:2px;height:13px;margin-left:2px;vertical-align:-2px;border-radius:1px;background:var(--dm-fg2);animation:bpblink 1s steps(1,end) infinite}
/* the choices an agent offers: white rows with the field's dimmed edge, the picked one a step stronger */
.thp[data-d] .tpx-opts{display:flex;flex-direction:column;gap:6px;margin-top:2px}
.thp[data-d] .tpx-opt{display:flex;align-items:center;gap:8px;width:100%;padding:8px 10px;border-radius:var(--dm-r-in);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent);font-size:13px;text-align:left;transition:background .2s,box-shadow .2s,transform .15s}
@media (hover:hover) and (pointer:fine){.thp[data-d] .tpx-opt:hover{background:var(--dm-row)}}
.thp[data-d] .tpx-opt:active{transform:scale(.99)}
.thp[data-d] .tpx-opt .k{width:20px;height:20px;border-radius:calc(6px * var(--dm-rk));display:grid;place-items:center;flex:none;background:var(--dm-chip);font-size:11px;font-weight:500;color:var(--dm-fg2)}
@media (hover:hover) and (pointer:fine){.thp[data-d] .tpx-opt:hover .k{background:var(--dm-surface)}}
.thp[data-d] .tpx-opt[aria-pressed="true"]{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-on) 50%,transparent)}
.thp[data-d] .tpx-opt[aria-pressed="true"] .k{background:var(--dm-hover);color:var(--dm-fg)}
/* once one is picked, the others are out of play */
.thp[data-d] .tpx-opts.done .tpx-opt:not([aria-pressed="true"]){opacity:.5;cursor:default;background:var(--dm-surface)}
/* the reply field: a quiet edge that steps up a grey with the focus */
.thp[data-d] .tpx-in{display:flex;align-items:center;gap:var(--dm-s-2);padding:4px 4px 4px 12px;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.thp[data-d] .tpx-in{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.thp[data-d] .tpx-in:has(.tpx-field:focus){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.thp[data-d] .tpx-field{flex:1;min-width:0;height:30px;border:0;outline:0;background:none;font-size:13px}
.thp[data-d] .tpx-field::placeholder{color:var(--dm-muted)}
.thp[data-d] .tpx-send{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;flex:none;background:var(--dm-accent);color:var(--dm-on-accent);transition:transform .15s,background .2s}
@media (hover:hover) and (pointer:fine){.thp[data-d] .tpx-send:hover{background:var(--dm-accent-2)}}
.thp[data-d] .tpx-send:active{transform:scale(.9)}
.thp[data-d] .tpx-send[disabled]{cursor:not-allowed;background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring)}
.thp[data-d] .tpx-send .i{width:14px;height:14px}
.thp[data-d] .tpx-new{animation:tpxin .5s var(--dm-ease) backwards}
@keyframes tpxin{from{opacity:0;transform:translateY(8px)}}
:root:not([data-style="soft"]) .thp[data-d] .tpx-av:not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-fg) 12%,transparent)}
:root:not([data-style="soft"]) .thp[data-d] .tpx-av[data-s="work"] .tpx-st:not(:where([data-style="soft"],[data-style="soft"] *)){animation:bpblink 1.1s steps(1,end) infinite}
:root:not([data-style="soft"]) .thp[data-d] .tpx-dots i:not(:where([data-style="soft"],[data-style="soft"] *)){animation:tpxdotbp 1.2s steps(1,end) infinite}
@keyframes tpxdotbp{0%,33%{opacity:1}34%,100%{opacity:.25}}
:root:not([data-style="soft"]) .thp[data-d] .tpx-dots i:nth-child(2):not(:where([data-style="soft"],[data-style="soft"] *)){animation-delay:.4s}:root:not([data-style="soft"]) .thp[data-d] .tpx-dots i:nth-child(3):not(:where([data-style="soft"],[data-style="soft"] *)){animation-delay:.8s}
:root:not([data-style="soft"]) .thp[data-d] .tpx-new:not(:where([data-style="soft"],[data-style="soft"] *)){animation:bpin .3s var(--dm-ease) backwards}

/* Deck: the threads as a stack of cards. A card behind shows its strip; the front one is the conversation */
.thp[data-d="deck"]{display:flex;flex-direction:column;gap:var(--dm-s-3);--dm-peek:32px}
.thp[data-d="deck"] .tpb-deck{position:relative;height:calc(344px + var(--dm-peek) * 2);touch-action:pan-y}
.thp[data-d="deck"] .tpb-card{position:absolute;left:0;right:0;bottom:0;height:344px;display:flex;flex-direction:column;border-radius:var(--dm-r-card);background:var(--dm-surface);box-shadow:var(--dm-shadow);transform-origin:50% 0;transform:translateY(calc(var(--dm-z) * var(--dm-peek) * -1)) scale(calc(1 - var(--dm-z) * .05));z-index:calc(10 - var(--dm-z));transition:transform .55s var(--dm-ease);will-change:transform}
/* the front card's deeper shadow fades in on a layer of its own, rather than switching the card's shadow in one frame */
.thp[data-d="deck"] .tpb-card::after{content:"";position:absolute;inset:0;border-radius:inherit;box-shadow:var(--dm-shadow-pop);opacity:0;transition:opacity .45s var(--dm-ease);pointer-events:none}
.thp[data-d="deck"] .tpb-card[data-z="0"]::after{opacity:1}
.thp[data-d="deck"] .tpb-card:not([data-z="0"]){cursor:pointer}
.thp[data-d="deck"] :is(.tpb-body,.tpx-in){transition:opacity .35s var(--dm-ease)}
.thp[data-d="deck"] .tpb-card:not([data-z="0"]) :is(.tpb-body,.tpx-in){opacity:0;pointer-events:none}
@media (hover:hover) and (pointer:fine){.thp[data-d="deck"] .tpb-card:not([data-z="0"]):hover{transform:translateY(calc(var(--dm-z) * var(--dm-peek) * -1 - 4px)) scale(calc(1 - var(--dm-z) * .05))}}
.thp[data-d="deck"] .tpb-card.drag{transition:none;cursor:grabbing}
.thp[data-d="deck"] .tpb-card.nudge{animation:tpbnudge .7s var(--dm-ease)}
@keyframes tpbnudge{30%{translate:0 -7px}60%{translate:0 1px}}
.thp[data-d="deck"] .tpb-ch{position:relative;display:flex;align-items:center;gap:10px;height:48px;padding:0 14px;flex:none}
.thp[data-d="deck"] .tpb-ch .tpx-av{width:26px;height:26px;border-radius:calc(8px * var(--dm-rk))}
.thp[data-d="deck"] .tpb-card:not([data-z="0"]) .tpb-ch{align-items:flex-start;padding-top:6px}
.thp[data-d="deck"] .tpb-card:not([data-z="0"]) .tpb-ct span{display:none}
.thp[data-d="deck"] .tpb-ct{flex:1;min-width:0;display:flex;flex-direction:column}
.thp[data-d="deck"] .tpb-ct b{font-weight:500;font-size:13.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.thp[data-d="deck"] .tpb-ct span{font-size:12px;color:var(--dm-fg2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.thp[data-d="deck"] .tpb-tag{flex:none}
.thp[data-d="deck"] .tpb-tag .spin{width:9px;height:9px}
.thp[data-d="deck"] .tpb-body{flex:1;min-height:0;display:flex;flex-direction:column;gap:var(--dm-s-3);padding:4px 14px 12px}
.thp[data-d="deck"] .tpb-card .tpx-in{margin:0 10px 10px}
/* under the deck, the way through it: previous, a grey dot for each thread (the one in front stretches to a darker pill,
   drawn with a clip so nothing is laid out again) and next */
.thp[data-d="deck"] .tpb-nav{display:flex;align-items:center;justify-content:center;gap:var(--dm-s-2)}
.thp[data-d="deck"] .tpb-dots{display:flex;gap:0;align-items:center}
.thp[data-d="deck"] .tpb-dot{display:grid;place-items:center;width:22px;height:16px;border-radius:calc(8px * var(--dm-rk))}
.thp[data-d="deck"] .tpb-dot i{display:block;width:22px;height:8px;border-radius:4px;background:var(--dm-rail);clip-path:inset(0 7px round 4px);transition:clip-path .45s var(--dm-ease),background .3s}
.thp[data-d="deck"] .tpb-dot[aria-selected="true"] i{clip-path:inset(0 0 round 4px);background:var(--dm-muted)}
.thp[data-d="deck"] .tpb-dot:focus-visible{outline-offset:3px}
:root:not([data-style="soft"]) .thp[data-d="deck"] .tpb-card:not(:where([data-style="soft"],[data-style="soft"] *)){transform:translate(calc(var(--dm-z) * 8px),calc(var(--dm-z) * var(--dm-peek) * -1));transition:transform .3s cubic-bezier(.2,.8,.2,1)}
@media (hover:hover) and (pointer:fine){:root:not([data-style="soft"]) .thp[data-d="deck"] .tpb-card:not([data-z="0"]):hover:not(:where([data-style="soft"],[data-style="soft"] *)){transform:translate(calc(var(--dm-z) * 8px),calc(var(--dm-z) * var(--dm-peek) * -1 - 3px))}}
:root:not([data-style="soft"]) .thp[data-d="deck"] .tpb-card:not([data-z="0"]):not(:where([data-style="soft"],[data-style="soft"] *)){box-shadow:0 0 0 1px color-mix(in srgb,var(--dm-rail) 60%,transparent)}
:root:not([data-style="soft"]) .thp[data-d="deck"] .tpb-card.nudge:not(:where([data-style="soft"],[data-style="soft"] *)){animation:tpbnudgebp .5s cubic-bezier(.2,.8,.2,1)}
@keyframes tpbnudgebp{50%{translate:0 -5px}}
:root:not([data-style="soft"]) .thp[data-d="deck"] .tpb-dot i:not(:where([data-style="soft"],[data-style="soft"] *)){transition:clip-path .25s cubic-bezier(.2,.8,.2,1),background .2s}

/* Focus: one thread at a time, with the agent's work live in it, one-tap replies and a switcher that flags waiting threads */
.thp[data-d="focus"]{display:flex;flex-direction:column;height:420px;padding:0}
.thp[data-d="focus"] .tpc-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-2);padding:10px 12px 10px 8px;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.thp[data-d="focus"] .tpc-sw{display:flex;align-items:center;gap:10px;min-width:0;padding:5px 8px 5px 5px;border-radius:var(--dm-r-in);text-align:left;transition:background .2s}
.thp[data-d="focus"] .tpc-sw[aria-expanded="true"]{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.thp[data-d="focus"] .tpc-sw:hover{background:var(--dm-row)}}
.thp[data-d="focus"] .tpc-sw:focus-visible{outline-offset:-2px;border-radius:var(--dm-r-in)}
.thp[data-d="focus"] .tpc-sw>.i{color:var(--dm-muted);flex:none}
.thp[data-d="focus"] .tpc-swt{display:flex;flex-direction:column;min-width:0}
.thp[data-d="focus"] .tpc-swt b{font-weight:500;font-size:13.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.thp[data-d="focus"] .tpc-swt span{font-size:12px;color:var(--dm-muted);white-space:nowrap}
.thp[data-d="focus"] .tpc-sw.in .tpc-swt,.thp[data-d="focus"] .tpc-sw.in .tpc-av{animation:tpxin .45s var(--dm-ease)}
/* how many of the other threads wait for you, on the switcher: the site's warn tag */
.thp[data-d="focus"] .tpc-nd{flex:none;min-width:20px;justify-content:center;animation:tpxin .45s var(--dm-ease)}
.thp[data-d="focus"] .tpc-nd[hidden]{display:none}
/* what the agent is doing: the site's grey tag, with a status dot */
.thp[data-d="focus"] .tpc-pill{flex:none}
.thp[data-d="focus"] .tpc-pd{color:var(--dm-ok-mark)}
.thp[data-d="focus"][data-s="work"] .tpc-pd{animation:tpxblink 1.4s var(--dm-ease-io) infinite}
/* a finished thread's status is the green done chip */
.thp[data-d="focus"][data-s="done"] .tpc-pill{background:var(--dm-ok-bg);color:var(--dm-ok)}
.thp[data-d="focus"][data-s="done"] .tpc-pd{color:var(--dm-ok)}
.thp[data-d="focus"][data-s="ask"] .tpc-pd{color:var(--dm-warn-mark)}
/* narrow: the status keeps its dot and says the rest to a screen reader, so the thread's name has the room */
@container (max-width:380px){.thp[data-d="focus"] .tpc-pill{padding:0;width:20px;justify-content:center}.thp[data-d="focus"] .tpc-pt{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}.thp[data-d="focus"] .tpc-h{padding-right:8px}}
.thp[data-d="focus"] .tpc-menu{width:272px;max-width:calc(100% - 16px)}
.thp[data-d="focus"] .tpc-menu .mi{gap:10px}
.thp[data-d="focus"] .tpc-menu .mi .tpx-av{width:26px;height:26px;border-radius:calc(8px * var(--dm-rk))}
.thp[data-d="focus"] .tpc-menu .mi-t{flex:1;min-width:0;display:flex;flex-direction:column}
.thp[data-d="focus"] .tpc-menu .mi-t b{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.thp[data-d="focus"] .tpc-menu .mi-t span{font-size:12px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
@media (hover:hover) and (pointer:fine){.thp[data-d="focus"] .tpc-menu .mi:is(:hover,.hl,[aria-checked="true"]) .mi-t span{color:var(--dm-fg2)}}
.thp[data-d="focus"] .tpc-menu .mi[aria-checked="true"]{font-weight:400}
.thp[data-d="focus"] .tpc-menu .tg{flex:none}
.thp[data-d="focus"] .tpc-body{flex:1;min-height:0;display:flex;flex-direction:column;gap:var(--dm-s-3);padding:14px 14px 10px}
.thp[data-d="focus"] .tpc-body.in{animation:tpcswap .5s var(--dm-ease)}
@keyframes tpcswap{from{opacity:0;transform:translateX(10px)}}
/* the agent's work, live in the thread: what it is doing, a bar that fills, and each part as it lands */
.thp[data-d="focus"] .tpc-work{display:flex;flex-direction:column;gap:8px;padding:10px 12px;border-radius:var(--dm-r-in);background:var(--dm-surface);box-shadow:var(--dm-shadow)}
.thp[data-d="focus"] .tpc-wh{display:flex;align-items:center;gap:var(--dm-s-2);font-size:12.5px}
.thp[data-d="focus"] .tpc-wh .brand{width:14px;height:14px}
.thp[data-d="focus"] .tpc-wh b{flex:1;min-width:0;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.thp[data-d="focus"] .tpc-wh .num{color:var(--dm-muted);font-size:12px}
.thp[data-d="focus"] .tpc-bar{height:4px;border-radius:2px;background:var(--dm-line);overflow:hidden}
.thp[data-d="focus"] .tpc-bar i{display:block;height:100%;border-radius:inherit;background:var(--dm-accent-mark);transform-origin:left;transform:scaleX(var(--dm-p,0));transition:transform .6s var(--dm-ease)}
.thp[data-d="focus"] .tpc-steps{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:3px;font-size:12px;color:var(--dm-muted)}
.thp[data-d="focus"] .tpc-steps li{display:flex;align-items:center;gap:7px}
.thp[data-d="focus"] .tpc-steps .g{width:12px;height:12px;display:grid;place-items:center;flex:none}
.thp[data-d="focus"] .tpc-steps .g .dot{width:5px;height:5px;color:var(--dm-faint)}
.thp[data-d="focus"] .tpc-steps .g .spin{width:10px;height:10px;color:var(--dm-fg2)}
.thp[data-d="focus"] .tpc-steps li.run{color:var(--dm-fg)}
.thp[data-d="focus"] .tpc-steps li.done{color:var(--dm-fg2)}
.thp[data-d="focus"] .tpc-steps li.done .g{color:var(--dm-ok)}
.thp[data-d="focus"] .tpc-work[data-s="done"] .tpc-wh b{color:var(--dm-fg)}
.thp[data-d="focus"] .tpc-work[data-s="done"] .tpc-bar i{background:var(--dm-ok)}
.thp[data-d="focus"] .tpc-qr{display:flex;gap:6px;padding:0 12px 8px;overflow-x:auto;scrollbar-width:none;min-height:38px;-webkit-mask-image:linear-gradient(90deg,#000 calc(100% - 28px),transparent);mask-image:linear-gradient(90deg,#000 calc(100% - 28px),transparent)}
