.thp[data-d="focus"] .tpx-in{margin:0 10px 10px}
/* the pull request the agent opened: a link to it */
.thp[data-d="focus"] .tpc-pr{display:flex;align-items:center;gap:10px;width:100%;padding:10px 12px;border-radius:var(--dm-r-in);background:var(--dm-surface);box-shadow:var(--dm-shadow);font-size:12.5px;text-align:left;transition:background .2s}
@media (hover:hover) and (pointer:fine){.thp[data-d="focus"] .tpc-pr:hover{background:var(--dm-row)}}
.thp[data-d="focus"] .tpc-pr .brand{width:18px;height:18px}
