.thp[data-d="focus"] .tpc-prt span{color:var(--dm-muted)}
.thp[data-d="focus"] .tpc-pr .tag{margin-left:auto}
:root:not([data-style="soft"]) .thp[data-d="focus"] .tpc-bar i:not(:where([data-style="soft"],[data-style="soft"] *)){transition:transform .4s steps(5,end)}
:root:not([data-style="soft"]) .thp[data-d="focus"][data-s="work"] .tpc-pd:not(:where([data-style="soft"],[data-style="soft"] *)){animation:bpblink 1.1s steps(1,end) infinite}
:root:not([data-style="soft"]) .thp[data-d="focus"] .tpc-q:not(:where([data-style="soft"],[data-style="soft"] *)){animation:bpin .3s var(--dm-ease) backwards}
:root:not([data-style="soft"]) .thp[data-d="focus"] .tpc-body.in:not(:where([data-style="soft"],[data-style="soft"] *)){animation:bpin .3s var(--dm-ease)}

