.atx-ctx-key{display:flex;justify-content:space-between;gap:var(--dm-s-2);font-size:11.5px;color:var(--dm-muted);margin-top:-4px}
.atx-ctx-key span{display:inline-flex;align-items:center;gap:var(--dm-s-1)}
.atx-ctx-key i{width:8px;height:8px;border-radius:var(--dm-r-xs);background:var(--dm-muted)}
.atx-ctx-list{list-style:none;margin:0 calc(-1 * var(--dm-s-2));padding:0;display:flex;flex-direction:column;min-height:208px}
