/* uploading: a short line in the accent along the foot of the tile, growing with a transform */
.atx-ctx-up{position:absolute;left:var(--dm-s-1);right:var(--dm-s-1);bottom:3px;height:2px;border-radius:var(--dm-r-xs);background:var(--dm-accent-mark);transform-origin:left;transform:scaleX(var(--dm-p,0));transition:transform .2s linear}
