@media (hover:hover) and (pointer:fine){.evr-vs-chip:not([data-f="all"]):hover{background:var(--dm-evr-tb);color:var(--dm-evr-t);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-evr-t) 35%,transparent)}}
.evr-vs-chip.on:not([data-f="all"]){background:var(--dm-surface);color:var(--dm-evr-t);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-on) 50%,transparent)}
.evr-vs-th,.evr-vs-r{display:grid;grid-template-columns:minmax(0,1fr) 30px 16px 30px 40px;align-items:center;column-gap:var(--dm-s-1)}
