@media (hover:hover) and (pointer:fine){.evr-vs-i:hover{background:var(--dm-row)}}
.evr-vs-i .tg{flex:none}
.evr-vs-i.fix .ar{color:var(--dm-ok)}
/* a regression sits on the amber: its tag, its marks and its Rerun white, its words in the amber's ink */
.evr-vs-i.reg{background:var(--dm-warn-bg)}
