.evr-vs-i.reg .evr-dot{background:var(--dm-evr-on-warn)}
.evr-vs-d{display:flex;flex-direction:column;gap:6px;padding:0 10px 10px 22px;font-size:12.5px}
.evr-vs-kv{display:flex;gap:var(--dm-s-2)}
.evr-vs-kv .k{width:62px;flex:none}
.evr-vs-d .pill{align-self:flex-start;margin-top:var(--dm-s-1);background:var(--dm-evr-on-warn);color:var(--dm-fg);box-shadow:var(--dm-shadow)}
@media (hover:hover) and (pointer:fine){.evr-vs-d .pill:hover{box-shadow:var(--dm-shadow-pop)}}
.evr-vs-none{margin:0;padding:var(--dm-s-3) 10px;font-size:12.5px;color:var(--dm-muted)}
/* narrow: a row's tint says regressed or fixed, so its name keeps the room; the count of each stays in the filters */
@container (max-width:380px){.evr-vs-r .tg{display:none}.evr-vs-mv{display:none}.evr-vs-th,.evr-vs-r{grid-template-columns:minmax(0,1fr) 24px 12px 24px 34px}}
:root:not([data-style="soft"]) .evr-vs-i.reg:not(:where([data-style="soft"],[data-style="soft"] *)){background:repeating-linear-gradient(135deg,transparent 0 5px,color-mix(in srgb,var(--dm-warn) 10%,transparent) 5px 6px),var(--dm-warn-bg)}
/* Score & judge: a gauge for the score and a bar for each kind of check, then the judge's reasoning on the case that
   failed, with the wrong words marked. Everything sits on white, the judge's part inside a dimmed outline */
.evr-jg{padding:var(--dm-s-3);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.evr-jg-h{display:flex;align-items:center;justify-content:space-between;gap:var(--dm-s-3);padding:2px 2px 0}
.evr-jg-ht{display:flex;flex-direction:column;min-width:0}
.evr-jg-ht b{font-weight:500}
.evr-jg-st{font-size:12.5px;color:var(--dm-muted)}
.evr-jg-run.spinning .i{animation:rot .8s linear infinite}
/* the score on top, centred, and the three kinds of check side by side under it (owner, 4 Nov: no bars stacked beside a chart) */
.evr-jg-top{display:flex;flex-direction:column;align-items:stretch;gap:var(--dm-s-3)}
/* the gauge: a grey half ring, and the score's arc turning into it, so it fills with a transform */
.evr-jg-g{position:relative;display:flex;flex-direction:column;align-items:center}
.evr-jg-arc{position:relative;width:132px;height:66px;overflow:hidden}
.evr-jg-arc .tr,.evr-jg-arc i{position:absolute;left:0;top:0;width:132px;height:132px;box-sizing:border-box;border-radius:50%}
.evr-jg-arc .tr{border:10px solid color-mix(in srgb,var(--dm-line) 85%,transparent)}
.evr-jg-arc i{border:10px solid transparent;border-bottom-color:var(--dm-gc,var(--dm-ok));border-left-color:var(--dm-gc,var(--dm-ok));transform:rotate(calc(-45deg + var(--dm-p,0) * 180deg));transition:transform 1.2s var(--dm-ease),border-color .4s}
.evr-jg-gv{position:absolute;top:38px;font-size:14px;font-weight:500}
.evr-jg-gl{margin-top:6px;font-size:11.5px;color:var(--dm-muted)}
.evr-jg-cats{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:var(--dm-s-4)}
.evr-jg-cats li{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:3px var(--dm-s-2);font-size:12.5px}
.evr-jg-cats .s{font-size:12px;color:var(--dm-fg2);font-variant-numeric:tabular-nums}
.evr-jg-cats .s .d{margin-left:var(--dm-s-1);color:var(--dm-bad)}
.evr-jg-cats .s .d.up{color:var(--dm-ok)}
.evr-jg-cats .b{grid-column:1/-1;height:5px;border-radius:3px;background:var(--dm-line);overflow:hidden}
.evr-jg-cats .b i{display:block;height:100%;border-radius:inherit;background:var(--dm-accent-mark);transform-origin:left;transform:scaleX(var(--dm-p,0));transition:transform 1s var(--dm-ease)}
.evr-jg-j{display:flex;flex-direction:column;gap:var(--dm-s-2);min-height:208px;padding:var(--dm-s-3);border-radius:var(--dm-r-card);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent);font-size:12.5px}
.evr-jg-j.go{animation:evrjgin .45s var(--dm-ease)}
@keyframes evrjgin{from{opacity:0;transform:translateY(8px)}}
.evr-jg-jh{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13px}
.evr-jg-jh b{flex:1;min-width:0;font-weight:500}
.evr-jg-jq{margin:0;padding:var(--dm-s-2) 10px;border-radius:calc(10px * var(--dm-rk));background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent);line-height:1.6;color:var(--dm-fg)}
.evr-jg-jr{margin:0;color:var(--dm-fg2);line-height:1.55}
.evr-jg-jr .who{display:inline-flex;align-items:center;gap:var(--dm-s-1);color:var(--dm-muted);margin-right:var(--dm-s-1)}
.evr-jg-ja{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-top:auto}
.evr-jg-ja .sp{flex:1}
.evr-jg-ja .ib[aria-pressed="true"]{background:var(--dm-accent-bg);color:var(--dm-accent-fg)}
.evr-jg-ja .lbl{font-size:12px;color:var(--dm-muted)}
.evr-jg-ok{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;flex:1;text-align:center;color:var(--dm-fg2)}
.evr-jg-ok>.i{width:22px;height:22px;color:var(--dm-ok)}
.evr-jg-ok b{font-weight:500;color:var(--dm-fg)}
:root:not([data-style="soft"]) .evr-jg-arc .tr:not(:where([data-style="soft"],[data-style="soft"] *)),:root:not([data-style="soft"]) .evr-jg-arc i:not(:where([data-style="soft"],[data-style="soft"] *)){border-radius:50%!important}
:root:not([data-style="soft"]) .evr-jg-arc i:not(:where([data-style="soft"],[data-style="soft"] *)){transition:transform .8s steps(8,end),border-color .3s}
:root:not([data-style="soft"]) .evr-jg-cats .b i:not(:where([data-style="soft"],[data-style="soft"] *)){transition:transform .6s steps(6,end)}
