.dm.asx-dm>.dm-main{align-items:stretch}
/* what the agent may do, in the site's tag tones: allow green, ask amber, block grey. On a grey highlight a grey tile or cell
   lifts to white (one step lighter in dark mode) */
.asx-dm{--dm-asx-al:var(--dm-ok);--dm-asx-al-bg:var(--dm-ok-bg);--dm-asx-as:var(--dm-warn);--dm-asx-as-bg:var(--dm-warn-bg);--dm-asx-bl:var(--dm-fg2);--dm-asx-bl-bg:var(--dm-chip);--dm-asx-lift:var(--dm-surface)}
