:root:not([data-style="soft"]) .asx-lp-fill:not(:where([data-style="soft"],[data-style="soft"] *)),:root:not([data-style="soft"]) .asx-lp-th:not(:where([data-style="soft"],[data-style="soft"] *)){transition:transform .3s steps(3,end)}
