/* Presets: Careful, Balanced and Bold, each with its colour on its tile (teal, the accent and violet, so the grid's green and
   amber keep meaning allow and ask) and a meter in the accent, then a grid of allow, ask and block for each tool */
.asx-ps{padding:var(--dm-s-3);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.asx-ps-pre{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}
