          swap($('span', b), opts[F[k].v][0]); b.setAttribute('aria-label', `${k === 'auto' ? 'Autonomy' : 'Time limit'}: ${opts[F[k].v][0]}`);
          if (k === 'auto') swap($('.asx-tb-lt .d', b.closest('.asx-tb-r')), AUTO[F.auto.v][1]);
