        await c.wait(600);
        Object.keys(F).forEach(k => saved[k] = F[k].v); order = []; done = true; saving = false;
        sv.innerHTML = saveHtml(); bar();
        if (cf.contains(document.activeElement) || sv === document.activeElement) tb[cur].focus({ preventScroll:true });
